import 'dart:convert';

final List<Map<String, dynamic>> schreibenModels = List<Map<String, dynamic>>.from(json.decode(r'''[{"id":"schreiben-1","title":"نموذج Schreiben رقم 1","description":"ثلاث مهام كتابية: بريد إلكتروني غير رسمي، مشاركة منتدى، رسالة رسمية.","tasks":[{"id":"schreiben-1-1","taskNumber":1,"typeAr":"بريد إلكتروني غير رسمي (إلى صديق)","typeDe":"Informeller E-Mail","wordCount":"حوالي 80 كلمة","promptAr":"صديقك الألماني \"لوكاس\" يسأل عن الأكل الذي تحبه. اكتب له بريداً قصيراً وأجب عن النقاط التالية:","promptDe":"Ihr deutscher Freund Lukas fragt Sie nach Ihrem Lieblingsessen. Schreiben Sie ihm eine E-Mail.","requirements":["اذكر نوع طعام تحبه جداً ولماذا.","اكتب أين تأكله عادةً (في البيت أم في المطعم).","اسأله عن طعامه المفضل.","اقترح أن تطبخا معاً في نهاية الأسبوع."],"usefulPhrases":[{"de":"Lieber Lukas, / Hallo Lukas,","ar":"عزيزي لوكاس / مرحباً لوكاس"},{"de":"Vielen Dank für deine E-Mail.","ar":"شكراً على إيميلك."},{"de":"Mein Lieblingsessen ist …, weil …","ar":"أكلتي المفضلة هي ... لأن ..."},{"de":"Am liebsten esse ich …","ar":"أحب أكل ... أكثر شيء."},{"de":"Normalerweise esse ich zu Hause.","ar":"عادة آكل في البيت."},{"de":"Was isst du am liebsten?","ar":"ماذا تحب أن تأكل؟"},{"de":"Wollen wir am Samstag zusammen kochen?","ar":"هل نطبخ معاً يوم السبت؟"},{"de":"Viele Grüße / Bis bald","ar":"تحياتي / إلى اللقاء قريباً"}],"sampleAnswer":"Hallo Lukas,\n\nvielen Dank für deine E-Mail! Du fragst nach meinem Lieblingsessen. Ich esse am liebsten Maqluba. Das ist ein syrisches Gericht mit Reis, Hühnerfleisch, Auberginen und Kartoffeln. Es schmeckt einfach super und erinnert mich an meine Familie.\n\nNormalerweise esse ich zu Hause, weil meine Mutter sehr gut kocht. Ins Restaurant gehe ich nur am Wochenende.\n\nUnd was isst du am liebsten? Magst du arabisches Essen?\n\nIch habe eine Idee: Wollen wir am Samstag zusammen kochen? Dann zeige ich dir, wie man Maqluba macht.\n\nViele Grüße\nSamir","sampleAnswerNotes":["ملاحظة: عدد الكلمات ≈ 90، وهذا ممتاز.","استُخدمت كل النقاط الأربع المطلوبة.","قواعد منوّعة: weil – زمن المضارع – ins Restaurant – سؤال مباشر – اقتراح باستخدام \"Wollen wir...?\"."]},{"id":"schreiben-1-2","taskNumber":2,"typeAr":"مشاركة في منتدى (Forum)","typeDe":"Forumbeitrag","wordCount":"حوالي 80 كلمة","promptAr":"قرأتَ هذا السؤال في منتدى: \"هل تعلّم الأطفال لغة ثانية مفيد أم مُضرّ؟\" اكتب رأيك مع إعطاء مثال من حياتك.","promptDe":"In einem Internet-Forum finden Sie folgende Frage: „Sind zwei Sprachen gut oder schlecht für Kinder?\" Schreiben Sie Ihre Meinung.","requirements":["قدّم نفسك بجملة قصيرة.","اكتب رأيك بوضوح (إيجابي أم سلبي).","اذكر سببين على الأقل.","أعطِ مثالاً من حياتك أو عائلتك."],"usefulPhrases":[{"de":"Meiner Meinung nach …","ar":"في رأيي ..."},{"de":"Ich finde, dass …","ar":"أرى أن ..."},{"de":"Einerseits … andererseits …","ar":"من جهة ... ومن جهة أخرى ..."},{"de":"Zum Beispiel …","ar":"على سبيل المثال ..."},{"de":"Ein Vorteil ist, dass …","ar":"من إيجابيات ذلك أن ..."},{"de":"Zum Schluss möchte ich sagen …","ar":"في الختام أودّ أن أقول ..."}],"sampleAnswer":"Hallo zusammen,\n\nich heiße Rania und komme aus Syrien. Ich lebe seit vier Jahren in Deutschland.\n\nMeiner Meinung nach ist es sehr gut, wenn Kinder zwei Sprachen sprechen. Erstens: Kinder lernen eine Sprache sehr schnell, besonders wenn sie jung sind. Zweitens: mit zwei Sprachen haben sie später bessere Chancen im Beruf und in der Familie.\n\nZum Beispiel spricht mein Sohn zu Hause Arabisch mit uns, und in der Kita spricht er Deutsch. Er ist jetzt 5 Jahre alt und versteht beides sehr gut. Er hat keine Probleme.\n\nNatürlich muss man geduldig sein. Aber am Ende ist das ein großer Vorteil für das Kind.\n\nViele Grüße\nRania","sampleAnswerNotes":["عدد الكلمات ≈ 115 (مقبول؛ الأفضل 80-120).","تم استخدام: Meiner Meinung nach – Erstens/Zweitens – Zum Beispiel – Zum Schluss."]},{"id":"schreiben-1-3","taskNumber":3,"typeAr":"رسالة رسمية (شكوى / استفسار)","typeDe":"Formeller Brief / formelle E-Mail","wordCount":"حوالي 40 كلمة","promptAr":"اشتريت هاتفاً جديداً من متجر إلكتروني، ولكنه لا يعمل. اكتب بريداً رسمياً إلى خدمة الزبائن. لا تنسَ التحية الرسمية والختام.","promptDe":"Sie haben ein Handy online bestellt. Das Gerät funktioniert nicht. Schreiben Sie eine formelle E-Mail an den Kundenservice.","requirements":["ابدأ بـ \"Sehr geehrte Damen und Herren\".","اذكر رقم الطلب أو التاريخ.","اشرح المشكلة باختصار.","اطلب حلاً (استبدال أو استرجاع المال).","اختم بـ \"Mit freundlichen Grüßen\"."],"usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"السيدات والسادة المحترمون،"},{"de":"Ich habe am … bei Ihnen … bestellt.","ar":"لقد طلبت في ... من عندكم ..."},{"de":"Die Bestellnummer ist …","ar":"رقم الطلب هو ..."},{"de":"Leider funktioniert das Gerät nicht.","ar":"للأسف الجهاز لا يعمل."},{"de":"Ich bitte Sie, … zu tun.","ar":"أرجو منكم أن تفعلوا ..."},{"de":"Bitte antworten Sie mir bis zum …","ar":"أرجو الردّ قبل تاريخ ..."},{"de":"Mit freundlichen Grüßen","ar":"مع خالص التحية"}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nam 05.10. habe ich bei Ihnen ein Handy bestellt (Bestellnummer: 78245). Leider funktioniert das Gerät nicht – es lässt sich nicht einschalten.\n\nIch bitte Sie, mir ein neues Gerät zu schicken oder mein Geld zurückzuerstatten.\n\nMit freundlichen Grüßen\nSamir Al-Ahmad","sampleAnswerNotes":["عدد الكلمات ≈ 45 (ممتاز للمهمة الثالثة).","يحتوي كل العناصر الرسمية: التحية - رقم الطلب - المشكلة - الطلب - الختام."]}]},{"id":"schreiben-2","title":"نموذج Schreiben رقم 2","description":"نموذج ثانٍ مع مواضيع المدرسة والرياضة والعمل.","tasks":[{"id":"schreiben-2-1","taskNumber":1,"typeAr":"بريد إلكتروني إلى صديق","typeDe":"Informeller E-Mail","wordCount":"حوالي 80 كلمة","promptAr":"صديقتك \"آنّا\" دعتك لحفلة عيد ميلادها يوم السبت. اكتبي لها إجابة.","promptDe":"Ihre Freundin Anna hat Sie zu ihrer Geburtstagsparty am Samstag eingeladen. Antworten Sie.","requirements":["اشكريها على الدعوة.","اكتبي هل تأتين أم لا، ولماذا.","اسألي عن شيء يجب أن تحضريه.","اكتبي ما الهدية التي ستحضرينها."],"usefulPhrases":[{"de":"Danke für deine Einladung!","ar":"شكراً على دعوتك!"},{"de":"Ich komme gern.","ar":"سآتي بكل سرور."},{"de":"Leider kann ich nicht kommen, weil …","ar":"للأسف لا أستطيع المجيء لأن ..."},{"de":"Soll ich etwas mitbringen?","ar":"هل يجب أن أحضر شيئاً؟"},{"de":"Ich bringe dir …","ar":"سأحضر لك ..."}],"sampleAnswer":"Liebe Anna,\n\ntausend Dank für deine Einladung! Natürlich komme ich sehr gern zu deiner Geburtstagsparty am Samstag. Ich freue mich schon!\n\nIch wollte dich fragen: Soll ich etwas mitbringen, zum Beispiel Salat oder Getränke? Ich kann auch gern einen Kuchen backen, wenn du möchtest.\n\nAls Geschenk bekommst du ein Buch. Ich weiß, du liest sehr gern Krimis.\n\nBis Samstag!\nDeine Leila"},{"id":"schreiben-2-2","taskNumber":2,"typeAr":"مشاركة في المنتدى","typeDe":"Forumsbeitrag","wordCount":"حوالي 80 كلمة","promptAr":"تقرأ في منتدى: \"هل يجب على كل طفل أن يمارس رياضة في المدرسة؟\" اكتب رأيك.","promptDe":"Sie lesen im Forum: „Soll jedes Kind in der Schule Sport machen?\" Schreiben Sie Ihre Meinung.","requirements":["رحّب وعرّف نفسك.","اكتب رأيك بوضوح.","اذكر سببين.","اكتب خلاصة قصيرة."],"sampleAnswer":"Hallo zusammen,\n\nich bin Khaled, 28 Jahre alt. Meiner Meinung nach ist Sport in der Schule sehr wichtig.\n\nErstens bleiben die Kinder so gesund. Heutzutage sitzen Kinder zu viel vor dem Handy oder am Computer. Zweitens lernen sie durch Sport in einer Gruppe zu arbeiten und Respekt zu zeigen.\n\nNatürlich sollten die Lehrer verstehen, wenn ein Kind krank ist. Aber im Allgemeinen ist Sport für alle gut.\n\nViele Grüße\nKhaled"},{"id":"schreiben-2-3","taskNumber":3,"typeAr":"رسالة رسمية (اعتذار)","typeDe":"Formeller Brief","wordCount":"حوالي 40 كلمة","promptAr":"لديك موعد غداً في Jobcenter، لكن لا تستطيع الحضور بسبب مرض ابنك. اعتذر واطلب موعداً جديداً.","promptDe":"Sie haben morgen einen Termin im Jobcenter, können aber nicht kommen, weil Ihr Kind krank ist. Entschuldigen Sie sich und bitten Sie um einen neuen Termin.","requirements":["استعمل التحية الرسمية.","اعتذر واذكر السبب.","اطلب موعداً جديداً واقترح وقتاً.","اختتم بشكل رسمي."],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nleider kann ich morgen nicht zu meinem Termin um 10:30 Uhr kommen, weil mein Sohn plötzlich krank geworden ist und ich zum Arzt muss.\n\nIch möchte mich dafür entschuldigen und bitte um einen neuen Termin. Nächste Woche am Dienstag oder Mittwoch wäre gut für mich.\n\nMit freundlichen Grüßen\nMaryam Al-Hassan"}]},{"id":"schreiben-3","title":"Schreiben – نموذج 3 (الحياة اليومية)","description":"دعوة لعيد ميلاد، رأي في موضوع تعليمي، شكوى رسمية.","tasks":[{"id":"schreiben-3-1","taskNumber":1,"typeAr":"دعوة شخصية / Einladung an einen Freund","typeDe":"E-Mail an einen Freund","promptAr":"صديقك سيزور ألمانيا لأول مرة. اكتب له رسالة تدعوه للإقامة عندك.","promptDe":"Ihr Freund / Ihre Freundin Kareem aus Damaskus kommt zum ersten Mal nach Deutschland zu Besuch. Schreiben Sie eine E-Mail (ca. 80 Wörter):","requirements":["لماذا فرحت برسالته؟","متى يأتي وكم سيبقى؟","ماذا ستفعلون معاً؟","ماذا يجب أن يحضر معه؟"],"wordCount":"حوالي 80 كلمة","imageUrl":"https://images.unsplash.com/photo-1527176930608-09cb256ab504?auto=format&fit=crop&w=800&q=70","imageAlt":"سفر بالطائرة","usefulPhrases":[{"de":"Ich freue mich riesig, dass …","ar":"أنا سعيد جداً أن ..."},{"de":"Du kannst gerne bei mir wohnen.","ar":"يمكنك أن تسكن عندي."},{"de":"Bring bitte … mit.","ar":"أحضر معك ... من فضلك."},{"de":"Ich hole dich vom Flughafen ab.","ar":"سأقابلك في المطار."},{"de":"Wir können … besuchen.","ar":"يمكننا زيارة ..."}],"sampleAnswer":"Lieber Kareem,\n\nvielen Dank für deine Nachricht! Ich freue mich riesig, dass du nach Deutschland kommst. Ich kann es kaum erwarten, dich endlich wiederzusehen.\n\nDu kannst gerne bei mir wohnen. Wann genau kommst du und wie lange bleibst du? Wir können zusammen das Brandenburger Tor besuchen, in den Park gehen und natürlich richtig deutsches Essen probieren!\n\nBring bitte etwas Warmes mit, denn hier ist es im Oktober schon kalt. Schick mir bitte deine Flugdaten, dann hole ich dich vom Flughafen ab.\n\nBis bald,\ndein Ahmad"},{"id":"schreiben-3-2","taskNumber":2,"typeAr":"تعليق في موقع تعليمي","typeDe":"Forenbeitrag","promptAr":"في موقع تعليمي يُسأل: \"هل تعلّم لغة جديدة في الحياة اليومية أفضل من المدرسة؟\" اكتب تعليقك.","promptDe":"Auf einer Sprachlern-Seite lesen Sie die Frage: \"Lernt man eine Sprache besser im Alltag als in der Schule?\" Schreiben Sie Ihre Meinung (ca. 80 Wörter).","requirements":["كيف تعلّمت أنت الألمانية حتى الآن؟","ماذا أفضل عند التعلم في الحياة اليومية؟","ماذا أفضل عند التعلم في المدرسة/الكورس؟","ما رأيك أنت؟ ولماذا؟"],"wordCount":"حوالي 80 كلمة","imageUrl":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?auto=format&fit=crop&w=800&q=70","imageAlt":"كتب وقاموس لتعلم اللغة","usefulPhrases":[{"de":"Meiner Meinung nach …","ar":"برأيي ..."},{"de":"Auf der einen Seite …, auf der anderen Seite …","ar":"من جهة ... ومن جهة أخرى ..."},{"de":"Im Alltag spricht man …","ar":"في الحياة اليومية يتكلم المرء ..."},{"de":"In der Schule lernt man die Grammatik …","ar":"في المدرسة يتعلم المرء القواعد ..."},{"de":"Ich finde es am besten, wenn man beides verbindet.","ar":"أرى أنه من الأفضل دمج الطريقتين."}],"sampleAnswer":"Hallo zusammen,\n\nich finde diese Frage sehr interessant. Ich lerne seit zwei Jahren Deutsch – im Kurs und im Alltag.\n\nAuf der einen Seite ist die Schule wichtig: Man lernt die Grammatik, das Schreiben und die Aussprache richtig. Ohne diese Basis spricht man immer falsch.\n\nAuf der anderen Seite ist der Alltag besser für das Sprechen. Man hat keine Angst, hört echte Sätze und kann direkt reagieren.\n\nMeiner Meinung nach ist beides nötig. Am besten lernt man, wenn man am Morgen einen Kurs besucht und am Nachmittag mit Deutschen spricht."},{"id":"schreiben-3-3","taskNumber":3,"typeAr":"شكوى رسمية","typeDe":"Beschwerde-Brief","promptAr":"اشتريت غسالة قبل أسبوعين، لكن صدرت أصواتاً غريبة منذ يومين. اكتب شكوى رسمية للمتجر.","promptDe":"Sie haben vor zwei Wochen bei \"Elektro Schmidt\" eine neue Waschmaschine gekauft. Seit zwei Tagen macht sie laute Geräusche. Schreiben Sie eine Beschwerde (ca. 80 Wörter).","requirements":["متى وأين اشتريت الغسالة؟","ما هي المشكلة بالضبط؟","ماذا تطلب من المتجر؟","حتى متى تنتظر الردّ؟"],"wordCount":"حوالي 80 كلمة","imageUrl":"https://images.unsplash.com/photo-1610557892470-55d9e80c0bce?auto=format&fit=crop&w=800&q=70","imageAlt":"غسالة كهربائية","usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"سيداتي وسادتي،"},{"de":"ich wende mich an Sie wegen …","ar":"أتوجّه إليكم بشأن ..."},{"de":"leider funktioniert … nicht richtig.","ar":"لسوء الحظ ... لا يعمل بشكل صحيح."},{"de":"Ich bitte Sie, … zu reparieren / zu erstatten.","ar":"أرجو منكم أن تصلحوا / تردّوا ..."},{"de":"Ich erwarte Ihre Antwort bis spätestens …","ar":"أنتظر ردّكم في موعد أقصاه ..."}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nich wende mich an Sie, weil ich am 5. März in Ihrem Geschäft \"Elektro Schmidt\" in Düsseldorf eine Waschmaschine der Marke Bosch gekauft habe. Die Rechnungsnummer lautet 2024-1234.\n\nLeider macht die Maschine seit zwei Tagen sehr laute Geräusche, besonders beim Schleudern. Ich habe alles richtig angeschlossen und die Bedienungsanleitung beachtet.\n\nIch bitte Sie, die Waschmaschine entweder schnell zu reparieren oder mir eine neue zu liefern. Da das Gerät noch in der Garantie ist, erwarte ich keine Kosten.\n\nBitte antworten Sie bis spätestens nächsten Freitag.\n\nMit freundlichen Grüßen\nMahmoud Ali"}]},{"id":"schreiben-4","title":"Schreiben – نموذج 4 (مواقف يومية)","description":"تأخير في عمل، شكوى من جار، رد على إعلان شقة. مع نصائح كتابة بالعربية لكل مهمة.","tasks":[{"id":"schreiben-4-1","taskNumber":1,"typeAr":"بريد رسمي للمدير: تأخّر عن العمل","typeDe":"E-Mail an den Chef","promptAr":"تأخّرت اليوم عن عملك بسبب الباصات. اكتب بريداً للمدير تعتذر فيه وتشرح السبب وتقترح حلاً.","promptDe":"Schreiben Sie eine E-Mail an Ihren Chef, Herrn Becker. Heute Morgen sind Sie zur Arbeit zu spät gekommen, weil die Busse Verspätung hatten.","requirements":["اعتذر بشكل مهذّب","اشرح ماذا حدث","اقترح كيف ستعوّض ذلك","اطلب رأيه أو موعداً للحديث معه"],"wordCount":"حوالي 80-100 كلمة","imageUrl":"https://images.unsplash.com/photo-1551836022-d5d88e9218df?auto=format&fit=crop&w=800&q=70","imageAlt":"محطة باصات في الصباح","usefulPhrases":[{"de":"Sehr geehrter Herr …","ar":"حضرة السيد المحترم..."},{"de":"Ich möchte mich aufrichtig entschuldigen.","ar":"أعتذر بصدق."},{"de":"Heute Morgen hatte der Bus große Verspätung.","ar":"اليوم في الصباح كان الباص متأخراً جداً."},{"de":"Als Ausgleich werde ich heute länger bleiben.","ar":"كتعويض سأبقى اليوم لمدة أطول."},{"de":"Bitte teilen Sie mir mit, wann ich mit Ihnen sprechen kann.","ar":"أرجو إعلامي متى يمكنني التحدث معك."},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswerNotes":["استخدم Sehr geehrter Herr Becker (لأنه رسمي).","اعتذر **في البداية**، اشرح السبب بدقة، ثم قدّم حلاً.","تجنّب الأعذار الطويلة. كن واضحاً ومختصراً."],"sampleAnswer":"Sehr geehrter Herr Becker,\n\nich möchte mich aufrichtig dafür entschuldigen, dass ich heute Morgen zu spät zur Arbeit gekommen bin.\n\nDer Grund war, dass mein Bus eine Verspätung von über 30 Minuten hatte. Auf der Anzeigetafel stand zuerst \"5 Minuten\", aber dann ist der Bus einfach nicht gekommen. Auch der nächste Bus war voll, sodass ich nicht einsteigen konnte.\n\nAls Ausgleich werde ich heute Abend gerne länger bleiben oder mein Mittagspause kürzen. In Zukunft werde ich früher aus dem Haus gehen, damit so etwas nicht wieder passiert.\n\nBitte teilen Sie mir mit, wann ich mit Ihnen darüber kurz sprechen kann.\n\nMit freundlichen Grüßen\nKhaled Ahmad"},{"id":"schreiben-4-2","taskNumber":2,"typeAr":"بريد لجارك: مشكلة الضوضاء","typeDe":"E-Mail an den Nachbarn","promptAr":"جارك في الطابق العلوي يصدر ضوضاء عالية في الليل. اكتب رسالة مهذبة لتطلب منه التهدئة.","promptDe":"Ihr Nachbar Herr Schmidt im Stockwerk über Ihnen macht abends nach 22 Uhr immer sehr laute Musik. Sie können nicht schlafen.","requirements":["حيِّه بشكل ودود","اشرح المشكلة بدون إساءة","اقترح حلاً (ساعات معينة، خفض الصوت...)","اشكره على تفهّمه"],"wordCount":"حوالي 80 كلمة","imageUrl":"https://images.unsplash.com/photo-1545454675-3531b543be5d?auto=format&fit=crop&w=800&q=70","imageAlt":"بناية سكنية في ألمانيا","usefulPhrases":[{"de":"Lieber Herr / liebe Frau …","ar":"عزيزي السيد / عزيزتي السيدة"},{"de":"Ich wende mich an Sie, weil …","ar":"أكتب إليك لأن..."},{"de":"Es stört mich, wenn …","ar":"يزعجني عندما..."},{"de":"Könnten Sie bitte … leiser machen?","ar":"هل يمكنك جعل ... أهدأ؟"},{"de":"Vielen Dank für Ihr Verständnis.","ar":"شكراً لتفهّمك."},{"de":"Mit freundlichen Grüßen / Viele Grüße","ar":"مع أطيب التحيات / تحيات"}],"sampleAnswerNotes":["كن **مهذباً جداً** — في ألمانيا الجار جزء مهم من الحياة اليومية.","لا تتّهمه مباشرة. استخدم \"ich-Form\" بدل \"Sie machen...\".","اقترح حلاً واقعياً (مثلاً: تخفيض الصوت بعد الـ22)."],"sampleAnswer":"Lieber Herr Schmidt,\n\nich hoffe, es geht Ihnen gut. Ich wende mich an Sie wegen einer kleinen Sache, die mir wichtig ist.\n\nIn den letzten Wochen ist die Musik aus Ihrer Wohnung nach 22 Uhr ziemlich laut. Leider kann ich dann nicht schlafen, weil mein Schlafzimmer direkt unter Ihrem Wohnzimmer ist. Morgens muss ich um 6 Uhr aufstehen.\n\nKönnten Sie die Musik bitte ab 22 Uhr ein bisschen leiser machen? Tagsüber ist das natürlich kein Problem.\n\nVielen Dank für Ihr Verständnis und einen schönen Abend!\n\nViele Grüße\nHassan Othman (Wohnung 2A)"},{"id":"schreiben-4-3","taskNumber":3,"typeAr":"استفسار عن شقة من إعلان","typeDe":"Anfrage zu einer Wohnung","promptAr":"رأيت إعلان شقة في الإنترنت. اكتب بريداً لصاحب الإعلان للاستفسار وتحديد موعد لرؤيتها.","promptDe":"Sie haben im Internet eine Anzeige für eine 2-Zimmer-Wohnung in München gesehen. Schreiben Sie eine E-Mail an die Vermieterin Frau Roth.","requirements":["عرّف عن نفسك (الاسم، المهنة)","اسأل أسئلة مهمة (الإيجار، التأشيرة، تاريخ الانتقال، الأثاث)","اطلب موعداً لمعاينة الشقة","اشكرها وودّعها بشكل رسمي"],"wordCount":"حوالي 80-100 كلمة","imageUrl":"https://images.unsplash.com/photo-1502672260266-1c1ef2d93688?auto=format&fit=crop&w=800&q=70","imageAlt":"شقة فارغة بإيجار","usefulPhrases":[{"de":"Sehr geehrte Frau Roth,","ar":"حضرة السيدة روت المحترمة،"},{"de":"Ich habe Ihre Anzeige im Internet gelesen.","ar":"قرأت إعلانك على الإنترنت."},{"de":"Ich interessiere mich für die Wohnung.","ar":"أنا مهتم بالشقة."},{"de":"Ich bin … von Beruf.","ar":"أعمل ..."},{"de":"Ist die Wohnung möbliert?","ar":"هل الشقة مفروشة؟"},{"de":"Wie hoch sind die Nebenkosten?","ar":"كم تبلغ التكاليف الإضافية؟"},{"de":"Wann könnte ich die Wohnung besichtigen?","ar":"متى يمكنني معاينة الشقة؟"},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswerNotes":["في ألمانيا مالك الشقة يقرأ **عشرات الرسائل** يومياً. كن واضحاً ومختصراً.","اذكر **مهنتك ودخلك** — مهم جداً لقبولك.","اقترح **3-4 مواعيد محددة** لزيارة الشقة، فهذا يسهّل الموافقة."],"sampleAnswer":"Sehr geehrte Frau Roth,\n\nich habe Ihre Anzeige für die 2-Zimmer-Wohnung in München-Schwabing gelesen und interessiere mich sehr dafür.\n\nMein Name ist Lara Khoury. Ich bin 28 Jahre alt und arbeite als Krankenschwester in einem städtischen Krankenhaus mit einem festen Vertrag. Ich suche eine Wohnung ab dem 1. März.\n\nIch habe noch ein paar Fragen:\n- Ist die Wohnung möbliert oder unmöbliert?\n- Wie hoch sind die Nebenkosten ungefähr?\n- Sind Haustiere erlaubt?\n\nKönnte ich die Wohnung bald besichtigen? Ich habe diese Woche am Mittwoch nach 17 Uhr und am Freitag den ganzen Tag Zeit.\n\nVielen Dank im Voraus für Ihre Antwort.\n\nMit freundlichen Grüßen\nLara Khoury"}]},{"id":"schreiben-5","title":"نموذج Schreiben رقم 5 (نمط Goethe – التوظيف)","description":"ثلاث مهام: بريد لزميل، مشاركة عن العمل عن بُعد، رسالة طلب وظيفة.","tasks":[{"id":"schreiben-5-1","taskNumber":1,"typeAr":"بريد إلكتروني لزميل عمل","typeDe":"E-Mail an Kollegen","wordCount":"حوالي 80 كلمة","promptAr":"زميلك \"ماركوس\" غاب أمس عن العمل. اكتب له بريداً تخبره ما حصل وتسأله عن صحته.","promptDe":"Ihr Kollege Markus war gestern nicht im Büro. Schreiben Sie ihm eine E-Mail.","requirements":["اسأله عن سبب غيابه وعن صحته.","أخبره بأهم شيء حصل في الاجتماع.","اعرض عليه مساعدتك إذا احتاج.","اقترح موعداً للقاء قبل اجتماع الجمعة."],"usefulPhrases":[{"de":"Hallo Markus,","ar":"مرحباً ماركوس،"},{"de":"wie geht es dir? Bist du krank?","ar":"كيف حالك؟ هل أنت مريض؟"},{"de":"In der Sitzung gestern haben wir … besprochen.","ar":"في اجتماع الأمس ناقشنا..."},{"de":"Falls du Hilfe brauchst, melde dich bei mir.","ar":"إن احتجت مساعدة فأخبرني."},{"de":"Können wir uns am Donnerstag kurz treffen?","ar":"هل نلتقي يوم الخميس باختصار؟"},{"de":"Gute Besserung!","ar":"سلامتك / شفاء عاجل!"}],"sampleAnswer":"Hallo Markus,\n\nich habe gemerkt, dass du gestern nicht im Büro warst. Ist alles in Ordnung? Bist du krank?\n\nIm Meeting haben wir das neue Projekt mit der Firma Schmidt besprochen. Der Chef möchte, dass wir bis Freitag einen ersten Plan vorbereiten. Falls du Hilfe brauchst, kann ich dir gerne meine Notizen schicken.\n\nHättest du am Donnerstag um 14 Uhr Zeit für ein kurzes Treffen? So können wir uns auf Freitag vorbereiten.\n\nGute Besserung und bis bald!\n\nViele Grüße\nAdel","sampleAnswerNotes":["كل النقاط الأربع موجودة بشكل واضح.","استخدام Konjunktiv II المهذّب: \"Hättest du Zeit?\" بدلاً من \"Hast du Zeit?\".","\"Gute Besserung\" تعبير لطيف وشائع."]},{"id":"schreiben-5-2","taskNumber":2,"typeAr":"مشاركة في منتدى عن العمل عن بُعد","typeDe":"Forumbeitrag – Homeoffice","wordCount":"حوالي 80 كلمة","promptAr":"قرأت في منتدى السؤال التالي: \"هل العمل من البيت أفضل من العمل في المكتب؟\" اكتب رأيك واذكر مزايا وعيوب.","promptDe":"Lesen Sie die Frage im Forum: „Ist Homeoffice besser als Büroarbeit?\" Schreiben Sie Ihre Meinung.","requirements":["اذكر رأيك بوضوح في البداية.","اذكر ميزتين على الأقل.","اذكر عيباً أو مشكلة.","اعطِ مثالاً من تجربتك أو من حياتك."],"usefulPhrases":[{"de":"Liebes Forum,","ar":"عزيزي المنتدى،"},{"de":"Meiner Meinung nach …","ar":"في رأيي..."},{"de":"Ein großer Vorteil ist, dass …","ar":"من أكبر المزايا أنّ..."},{"de":"Allerdings gibt es auch Nachteile.","ar":"غير أنّ هناك عيوباً أيضاً."},{"de":"Aus eigener Erfahrung kann ich sagen, dass …","ar":"من تجربتي يمكنني القول إنّ..."},{"de":"Zusammenfassend …","ar":"باختصار..."}],"sampleAnswer":"Liebes Forum,\n\nich finde das Thema sehr interessant. Meiner Meinung nach hat das Homeoffice viele Vorteile.\n\nErstens spart man viel Zeit, weil man nicht zur Arbeit fahren muss. Zweitens kann man flexibler arbeiten und sich besser auf schwierige Aufgaben konzentrieren.\n\nAllerdings hat das Homeoffice auch Nachteile. Man fühlt sich oft einsam und der Kontakt zu den Kollegen geht verloren. Aus eigener Erfahrung kann ich sagen, dass mir die Mittagspause mit dem Team manchmal sehr fehlt.\n\nZusammenfassend finde ich eine Mischung am besten: zwei Tage zu Hause, drei Tage im Büro.\n\nViele Grüße,\nLayla","sampleAnswerNotes":["ابدأ برأي واضح: \"ich finde das Thema interessant\".","استخدم الترقيم: Erstens / Zweitens / Allerdings / Zusammenfassend.","الحلّ الوسط في النهاية يثبت قدرتك على التفكير المتوازن."]},{"id":"schreiben-5-3","taskNumber":3,"typeAr":"رسالة تقدّم لوظيفة (رسمي)","typeDe":"Bewerbungsschreiben","wordCount":"حوالي 80 كلمة","promptAr":"قرأت إعلان وظيفة \"بائع/ة في متجر إلكترونيات\" على الإنترنت. اكتب رسالة تقدّم رسمية تذكر فيها:","promptDe":"Sie haben eine Stellenanzeige für „Verkäufer/in in einem Elektronikgeschäft\" gelesen. Schreiben Sie eine Bewerbung.","requirements":["اذكر مصدر الإعلان.","قدّم نفسك ومهنتك السابقة.","اذكر سبباً واحداً يجعلك مناسباً للوظيفة.","اطلب مقابلة شخصية."],"usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"حضرات السيدات والسادة،"},{"de":"mit großem Interesse habe ich Ihre Anzeige gelesen.","ar":"بكل اهتمام قرأت إعلانكم."},{"de":"Ich bewerbe mich um die Stelle als …","ar":"أتقدم لوظيفة..."},{"de":"In meinem Heimatland habe ich als … gearbeitet.","ar":"في بلدي عملت كـ..."},{"de":"Ich bin pünktlich, freundlich und arbeite gerne im Team.","ar":"أنا منضبط، ودود وأعمل بفريق."},{"de":"Ich freue mich auf Ihre Antwort.","ar":"أتطلع لردكم."},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nmit großem Interesse habe ich Ihre Anzeige im Internetportal \"JobFinder.de\" gelesen und bewerbe mich hiermit um die Stelle als Verkäufer in Ihrem Elektronikgeschäft.\n\nMein Name ist Omar Shamsi. Ich bin 28 Jahre alt und komme aus Syrien. In meinem Heimatland habe ich vier Jahre lang in einem Computer-Laden als Verkäufer gearbeitet. Ich kenne mich daher sehr gut mit Smartphones, Laptops und Zubehör aus.\n\nIch bin freundlich, geduldig und spreche Arabisch und Deutsch (B1).\n\nÜber die Möglichkeit eines persönlichen Gesprächs würde ich mich sehr freuen.\n\nMit freundlichen Grüßen\nOmar Shamsi","sampleAnswerNotes":["استخدم \"mit großem Interesse\" — قياسي في طلبات التوظيف.","اذكر مصدر الإعلان بدقّة.","اذكر خبرتك السابقة وما يميّزك (لغات، مهارات).","انهِ بطلب مقابلة + \"Mit freundlichen Grüßen\"."]}]},{"id":"schreiben-6","title":"Schreiben – نموذج 6 (مواقف عائلية واجتماعية)","description":"دعوة لزواج، نقاش في منتدى عن تربية الأطفال، طلب موعد مع المدرّس.","tasks":[{"id":"schreiben-6-1","taskNumber":1,"typeAr":"دعوة عائلية (بريد غير رسمي)","typeDe":"Einladung zur Hochzeit","promptAr":"صديقك الألماني سيتزوّج وسألك أن تأتي معه قبل العرس بأسبوع لتساعده. اكتب له بريداً.","promptDe":"Ihr deutscher Freund Tobias heiratet bald. Er möchte, dass Sie eine Woche vor der Hochzeit zu ihm kommen, um zu helfen. Schreiben Sie ihm eine E-Mail.","requirements":["اشكره على الدعوة وعبّر عن سعادتك","اخبره أنك ستأتي وحدّد متى","اسأل بماذا يحتاج المساعدة","اقترح أن تشتري هدية معه"],"wordCount":"حوالي 80 كلمة","imageUrl":"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=800&q=70","imageAlt":"حفل زفاف","usefulPhrases":[{"de":"Vielen Dank für die Einladung.","ar":"شكراً للدعوة."},{"de":"Ich freue mich riesig für dich!","ar":"أنا سعيد جداً لك!"},{"de":"Ich komme gerne schon eine Woche vorher.","ar":"سآتي بكل سرور قبل أسبوع."},{"de":"Sag mir Bescheid, wo ich helfen kann.","ar":"أخبرني أين يمكنني المساعدة."},{"de":"Sollen wir zusammen ein Geschenk besorgen?","ar":"هل نشتري هدية معاً؟"},{"de":"Liebe Grüße","ar":"تحياتي القلبية"}],"sampleAnswerNotes":["استخدم \"Lieber Tobias\" لأنه صديق.","احرص على ذكر التاريخ بدقّة وكيف ستصل إليه.","كن دافئاً وعفوياً — هذا بريد غير رسمي."],"sampleAnswer":"Lieber Tobias,\n\nvielen Dank für deine Einladung – ich freue mich riesig für dich und Anna! Natürlich komme ich gerne schon eine Woche vorher und helfe euch bei den Vorbereitungen.\n\nIch plane, am Samstag, den 15. Juni, mit dem Zug anzukommen. Sag mir bitte Bescheid, ob das passt und wo ich genau helfen kann – Einladungen verschicken, Saal dekorieren oder vielleicht beim Essen?\n\nAußerdem möchte ich ein gemeinsames Geschenk mit dir besorgen, falls du noch Ideen hast. Was meinst du?\n\nBis bald, mein Freund!\n\nLiebe Grüße,\nOmar"},{"id":"schreiben-6-2","taskNumber":2,"typeAr":"منتدى: نقاش عن تربية الأطفال والشاشات","typeDe":"Forumbeitrag","promptAr":"في منتدى للآباء، أحدهم كتب: \"أنا ضد إعطاء الهواتف للأطفال قبل سن 14\". اكتب رأيك.","promptDe":"In einem Forum schreibt ein Vater: \"Kinder unter 14 sollten kein Handy haben.\" Schreiben Sie Ihren Beitrag dazu.","requirements":["عبّر عن رأيك بوضوح (موافق/ضد)","قدّم سببين على الأقل","اذكر تجربتك أو تجربة شخص تعرفه","اقترح حلاً وسطاً"],"wordCount":"حوالي 80 كلمة","usefulPhrases":[{"de":"Meiner Meinung nach …","ar":"برأيي ..."},{"de":"Ich stimme dem nicht ganz zu.","ar":"لا أوافق تماماً."},{"de":"Auf der einen Seite … auf der anderen Seite …","ar":"من ناحية... ومن ناحية أخرى..."},{"de":"In meiner Familie …","ar":"في عائلتي ..."},{"de":"Ein Kompromiss wäre …","ar":"الحل الوسط هو ..."},{"de":"Wichtig finde ich, dass die Eltern Regeln aufstellen.","ar":"أرى أنه من المهم أن يضع الأهل قواعد."}],"sampleAnswerNotes":["افتح برأيك مباشرة (Ich finde / Meiner Meinung nach).","استخدم Konnektoren: außerdem, jedoch, deshalb.","اذكر مثالاً حقيقياً = درجة إضافية."],"sampleAnswer":"Meiner Meinung nach ist diese Regel zu streng. Ein totales Verbot bis 14 finde ich nicht realistisch, weil heute fast alle Klassenkameraden ein Handy haben.\n\nAuf der anderen Seite verstehe ich die Sorge der Eltern. Soziale Medien können Kinder unter Druck setzen, und manche verbringen zu viel Zeit am Bildschirm.\n\nBei uns zu Hause hat meine Tochter (12) ein einfaches Handy ohne Internet. Sie kann uns anrufen, aber spielt nicht stundenlang. Das funktioniert sehr gut.\n\nEin Kompromiss wäre also: ein Handy mit klaren Regeln, statt eines kompletten Verbots."},{"id":"schreiben-6-3","taskNumber":3,"typeAr":"بريد رسمي للمدرّس: طلب موعد لمناقشة درجات الابن","typeDe":"E-Mail an den Lehrer","promptAr":"ابنك في المدرسة، حصل على درجات سيئة في الرياضيات. اكتب بريداً للمدرّس تطلب فيه موعداً للقاء.","promptDe":"Ihr Sohn hat schlechte Noten in Mathematik bekommen. Schreiben Sie eine E-Mail an den Klassenlehrer, Herrn Müller, und bitten Sie um einen Termin.","requirements":["حيِّ المدرّس بشكل رسمي","اشرح سبب البريد (الدرجات)","اطلب موعداً للقاء وحدّد وقتك المتاح","اطلب نصيحة لمساعدة ابنك في البيت"],"wordCount":"حوالي 80-100 كلمة","usefulPhrases":[{"de":"Sehr geehrter Herr Müller,","ar":"حضرة السيد مولر المحترم،"},{"de":"mit Sorge habe ich die letzten Noten meines Sohnes gesehen.","ar":"بقلق لاحظتُ درجات ابني الأخيرة."},{"de":"Ich möchte gerne mit Ihnen sprechen.","ar":"أودّ التحدّث معك."},{"de":"Hätten Sie nächste Woche Zeit für ein Gespräch?","ar":"هل لديك وقت الأسبوع القادم لمحادثة؟"},{"de":"Wie kann ich ihn zu Hause unterstützen?","ar":"كيف أستطيع دعمه في البيت؟"},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswerNotes":["افتح بـ Sehr geehrter Herr Müller.","اظهر اهتمامك (mit Sorge / es liegt mir am Herzen).","كن مرناً في اقتراح الموعد."],"sampleAnswer":"Sehr geehrter Herr Müller,\n\nmit Sorge habe ich gesehen, dass mein Sohn Karim in Mathematik in letzter Zeit deutlich schlechtere Noten bekommen hat. Da mir seine Schullaufbahn sehr wichtig ist, möchte ich gerne mit Ihnen über die Situation sprechen.\n\nHätten Sie nächste Woche Zeit für ein kurzes Gespräch? Ich kann am Mittwoch oder Donnerstag nach 15 Uhr in die Schule kommen, andere Tage sind aber auch möglich.\n\nAußerdem würde ich mich freuen zu erfahren, wie ich Karim zu Hause besser unterstützen kann – vielleicht mit zusätzlichen Übungen oder einem Nachhilfelehrer.\n\nVielen Dank im Voraus für Ihre Zeit.\n\nMit freundlichen Grüßen\nYusuf Haddad"}]},{"id":"schreiben-7","title":"Schreiben – نموذج 7 (الإدارة والمكاتب الرسمية)","description":"تواصل مع Krankenkasse، شكوى مالية لـ Jobcenter، استفسار من Bürgeramt — مهم جداً للسوريين.","tasks":[{"id":"schreiben-7-1","taskNumber":1,"typeAr":"بريد رسمي للتأمين الصحي: تغيير العنوان","typeDe":"E-Mail an die Krankenkasse","promptAr":"انتقلت إلى شقة جديدة. اكتب للتأمين الصحي (AOK) لإبلاغهم بالعنوان الجديد.","promptDe":"Sie sind in eine neue Wohnung umgezogen. Schreiben Sie eine E-Mail an Ihre Krankenkasse (AOK), um Ihre neue Adresse mitzuteilen.","requirements":["اذكر اسمك ورقم تأمينك","اذكر العنوان القديم والجديد","اطلب تأكيد استلام البريد","اسأل إذا كانت بطاقة جديدة ضرورية"],"wordCount":"حوالي 80 كلمة","usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"سيداتي سادتي المحترمين،"},{"de":"hiermit teile ich Ihnen meine neue Adresse mit.","ar":"بهذا أعلمكم بعنواني الجديد."},{"de":"Meine Versichertennummer lautet …","ar":"رقم تأميني هو ..."},{"de":"Bitte bestätigen Sie den Erhalt dieser Nachricht.","ar":"الرجاء تأكيد استلام هذه الرسالة."},{"de":"Ist eine neue Versichertenkarte erforderlich?","ar":"هل بطاقة تأمين جديدة ضرورية؟"},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswerNotes":["دائماً ابدأ بـ \"Sehr geehrte Damen und Herren\" مع المؤسسات.","ضع رقم التأمين بوضوح ليجدوك بسرعة.","كن مختصراً ومحدّداً."],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nhiermit möchte ich Ihnen mitteilen, dass ich seit dem 1. März in eine neue Wohnung umgezogen bin. Bitte aktualisieren Sie meine Daten in Ihrem System.\n\nMein Name: Mohammed Alsalim\nVersichertennummer: A123456789\nAlte Adresse: Hauptstraße 12, 60311 Frankfurt\nNeue Adresse: Bergweg 8, 4. Stock, 60439 Frankfurt\n\nBitte bestätigen Sie mir den Erhalt dieser E-Mail. Außerdem möchte ich gerne wissen, ob ich eine neue Versichertenkarte mit der neuen Adresse beantragen muss.\n\nVielen Dank im Voraus.\n\nMit freundlichen Grüßen\nMohammed Alsalim"},{"id":"schreiben-7-2","taskNumber":2,"typeAr":"منتدى: نقاش حول تعلّم اللغة الألمانية","typeDe":"Forumbeitrag","promptAr":"في منتدى المهاجرين، شخص يقول: \"تعلّم الألمانية مستحيل بدون مدرّس\". اكتب رأيك.","promptDe":"In einem Migranten-Forum schreibt jemand: \"Ohne Lehrer kann man Deutsch nicht lernen.\" Schreiben Sie Ihre Meinung.","requirements":["عبّر عن رأيك بوضوح","اذكر تجربتك الشخصية","اذكر طرقاً ساعدتك","انصح القارئ بشيء عملي"],"wordCount":"حوالي 80 كلمة","usefulPhrases":[{"de":"Das stimmt nur teilweise.","ar":"هذا صحيح جزئياً."},{"de":"Aus eigener Erfahrung kann ich sagen, …","ar":"من تجربتي الشخصية، أستطيع القول إن..."},{"de":"Ich habe vor allem mit Apps gelernt.","ar":"تعلّمت بشكل أساسي بالتطبيقات."},{"de":"Mein Tipp ist: …","ar":"نصيحتي هي: ..."},{"de":"Sprachpartner finden ist sehr wichtig.","ar":"إيجاد شريك للتحدث مهم جداً."}],"sampleAnswer":"Das stimmt meiner Meinung nach nur teilweise. Natürlich hilft ein Lehrer enorm, vor allem bei der Aussprache und der Grammatik. Aber unmöglich ohne Lehrer? Ich denke, das ist übertrieben.\n\nAus eigener Erfahrung: Ich habe das Niveau A2 hauptsächlich mit YouTube-Videos und einer App erreicht. Erst danach habe ich einen Kurs besucht. Das Wichtigste ist, jeden Tag etwas zu üben und mit echten Menschen zu sprechen, zum Beispiel Nachbarn oder im Sportverein.\n\nMein Tipp: Apps + Tandempartner + ein paar Stunden mit Lehrer = die beste Mischung."},{"id":"schreiben-7-3","taskNumber":3,"typeAr":"شكوى رسمية لـ Jobcenter: تأخير في الدفع","typeDe":"Beschwerde beim Jobcenter","promptAr":"منذ شهرين لم تستلم راتب البطالة (Bürgergeld). اكتب شكوى رسمية للـ Jobcenter.","promptDe":"Seit zwei Monaten haben Sie kein Bürgergeld erhalten. Schreiben Sie eine Beschwerde an das Jobcenter.","requirements":["اذكر اسمك ورقم ملفك (Kundennummer)","اشرح المشكلة بدقّة (متى آخر دفعة)","اطلب توضيحاً وحلاً عاجلاً","اذكر أن الوضع المالي صعب"],"wordCount":"حوالي 100 كلمة","imageUrl":"https://images.unsplash.com/photo-1450101499163-c8848c66ca85?auto=format&fit=crop&w=800&q=70","imageAlt":"مكتب رسمي","usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"سيداتي سادتي المحترمين،"},{"de":"hiermit beschwere ich mich über …","ar":"بهذا أتقدّم بشكوى بخصوص..."},{"de":"meine Kundennummer lautet …","ar":"رقم ملفي هو..."},{"de":"Die letzte Zahlung erhielt ich am …","ar":"آخر دفعة استلمتها في..."},{"de":"Meine finanzielle Lage ist sehr schwierig.","ar":"وضعي المالي صعب جداً."},{"de":"Ich bitte um eine schnelle Klärung.","ar":"أرجو توضيحاً عاجلاً."},{"de":"Mit freundlichen Grüßen","ar":"مع أطيب التحيات"}],"sampleAnswerNotes":["استخدم \"hiermit beschwere ich mich\" — صيغة شكوى رسمية.","ضع رقم الملف بوضوح في البداية.","اطلب رداً ضمن إطار زمني (z.B. \"innerhalb einer Woche\")."],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nhiermit beschwere ich mich, dass ich seit zwei Monaten kein Bürgergeld erhalten habe. Meine Kundennummer lautet 12345678/JC.\n\nDie letzte Zahlung erhielt ich am 15. Februar. Seitdem ist nichts mehr auf meinem Konto eingegangen, obwohl meine Bewilligung bis Ende Juli läuft. Auf meine zwei vorherigen Anrufe habe ich leider keine Antwort bekommen.\n\nMeine finanzielle Lage ist inzwischen sehr schwierig: Miete, Strom und Lebensmittel kann ich kaum bezahlen.\n\nIch bitte Sie deshalb dringend um eine schnelle Klärung dieses Problems – am besten innerhalb einer Woche – und um eine schriftliche Erklärung, warum die Zahlungen ausgeblieben sind.\n\nMit freundlichen Grüßen\nAhmad Khalil"}]},{"id":"schreiben-8","title":"نموذج Schreiben رقم 8 — رسائل عمليّة شائعة","description":"ثلاث مهام من الحياة اليوميّة: تأجيل موعد، شكوى من طلب أونلاين، دعوة لحفل ميلاد.","tasks":[{"id":"schreiben-8-1","taskNumber":1,"typeAr":"تأجيل موعد طبيب","typeDe":"Arzttermin verschieben","promptAr":"كان عندك موعد عند الطبيب (Hausarzt) يوم الخميس الساعة 10:00 لكن لا تستطيع الحضور بسبب العمل. اكتب رسالة لتغيير الموعد.","promptDe":"Sie haben am Donnerstag um 10:00 einen Termin bei Ihrem Hausarzt, können aber wegen der Arbeit nicht kommen. Schreiben Sie eine E-Mail, um den Termin zu verschieben.","requirements":["اعتذر بأدب","اشرح السبب باختصار","اقترح موعدين بديلَين","اطلب التأكيد كتابيّاً"],"wordCount":"حوالي 70-80 كلمة","imageUrl":"https://images.unsplash.com/photo-1551601651-2a8555f1a136?auto=format&fit=crop&w=800&q=70","imageAlt":"موعد طبي","usefulPhrases":[{"de":"Sehr geehrte Frau / Sehr geehrter Herr Dr. ...,","ar":"دكتورة/دكتور المحترم،"},{"de":"leider kann ich meinen Termin am ... nicht wahrnehmen.","ar":"للأسف لا أستطيع حضور موعدي يوم..."},{"de":"der Grund ist, dass ich beruflich verhindert bin.","ar":"السبب أنّي مرتبط بعمل."},{"de":"Wäre es möglich, den Termin auf ... zu verschieben?","ar":"هل بالإمكان تأجيل الموعد إلى...؟"},{"de":"Alternativ käme auch ... in Frage.","ar":"بدلاً من ذلك يمكن أيضاً..."},{"de":"Ich bitte um eine kurze Bestätigung.","ar":"أرجو تأكيداً قصيراً."}],"sampleAnswerNotes":["استخدم صيغة \"Sehr geehrte/r\" مع اسم الطبيب.","اقترح موعدَين بديلَين على الأقلّ — يساعد السكرتيرة."],"sampleAnswer":"Sehr geehrte Frau Dr. Schmidt,\n\nleider kann ich meinen Termin am Donnerstag um 10:00 nicht wahrnehmen. Der Grund ist, dass ich an diesem Tag beruflich verhindert bin und nicht von der Arbeit weg kann.\n\nIch möchte den Termin gerne verschieben. Wäre es möglich, einen neuen Termin am kommenden Montag um 9:00 oder am Mittwoch um 16:00 zu bekommen?\n\nÜber eine kurze Bestätigung per E-Mail wäre ich sehr dankbar.\n\nVielen Dank im Voraus und mit freundlichen Grüßen,\nYara Hassan"},{"id":"schreiben-8-2","taskNumber":2,"typeAr":"شكوى من طلب أونلاين معطوب","typeDe":"Reklamation einer Online-Bestellung","promptAr":"طلبت سمّاعات بلوتوث من متجر أونلاين قبل أسبوع. وصلت اليوم لكنّها لا تشتغل أصلاً. اكتب رسالة شكوى تطلب فيها إعادة المال أو استبدال المنتج.","promptDe":"Sie haben vor einer Woche Bluetooth-Kopfhörer in einem Online-Shop bestellt. Heute sind sie angekommen, aber sie funktionieren nicht. Schreiben Sie eine Reklamation und fordern Sie Rückerstattung oder Ersatz.","requirements":["اذكر رقم الطلب وتاريخه","صف العطل بدقّة","اطلب حلّاً واضحاً (استرداد/استبدال)","حدّد إطاراً زمنيّاً للردّ"],"wordCount":"حوالي 90-100 كلمة","imageUrl":"https://images.unsplash.com/photo-1505740420928-5e560c06d30e?auto=format&fit=crop&w=800&q=70","imageAlt":"سمّاعات بلوتوث","usefulPhrases":[{"de":"mit großem Bedauern muss ich Ihnen mitteilen, dass ...","ar":"مع الأسف الشديد، يجب أن أخبركم أنّ..."},{"de":"meine Bestellnummer lautet ...","ar":"رقم طلبي هو..."},{"de":"der Artikel funktioniert leider nicht.","ar":"المنتج لا يعمل للأسف."},{"de":"Ich bitte um Rückerstattung des Kaufpreises.","ar":"أرجو استرداد ثمن الشراء."},{"de":"Alternativ erwarte ich Ersatz innerhalb von ... Tagen.","ar":"كبديل، أتوقّع منتجاً بديلاً خلال..."},{"de":"Bitte teilen Sie mir mit, wie wir verfahren sollen.","ar":"أرجو إخباري بالخطوات التالية."}],"sampleAnswerNotes":["كن واضحاً في وصف العطل (لا يشحن / لا يصدر صوت).","استخدم رقم الطلب بدقّة — مفتاح الردّ السريع."],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nmit großem Bedauern muss ich mich über Ihre Lieferung beschweren. Meine Bestellnummer lautet B-2025-09812 und wurde am 15. März aufgegeben.\n\nHeute sind die Bluetooth-Kopfhörer angekommen, jedoch lassen sie sich überhaupt nicht einschalten. Ich habe sie mehrere Stunden geladen, aber das Gerät reagiert nicht. Offensichtlich liegt ein Defekt vor.\n\nIch bitte Sie höflich um eine Rückerstattung des vollen Kaufpreises (89,99 €) auf mein ursprüngliches Konto. Alternativ akzeptiere ich auch einen kostenlosen Ersatz innerhalb von 7 Tagen.\n\nBitte teilen Sie mir bis Ende der Woche mit, wie wir verfahren sollen, damit ich die defekte Ware zurücksenden kann.\n\nMit freundlichen Grüßen,\nOmar Aziz"},{"id":"schreiben-8-3","taskNumber":3,"typeAr":"دعوة صديق لحفل ميلاد","typeDe":"Einladung zum Geburtstag","promptAr":"سيكون عيد ميلادك السبت القادم في البيت. اكتب رسالة لصديقك تدعوه للحفل.","promptDe":"Am kommenden Samstag haben Sie Geburtstag und feiern zu Hause. Schreiben Sie Ihrem Freund eine E-Mail und laden Sie ihn ein.","requirements":["ابدأ بصيغة شخصيّة وأخبره بالمناسبة","حدّد مكان وزمان وموضوع الحفل","اطلب منه أن يحضر شيئاً (مشروب/سلطة)","اطلب التأكيد قبل الجمعة"],"wordCount":"حوالي 70-80 كلمة","imageUrl":"https://images.unsplash.com/photo-1513151233558-d860c5398176?auto=format&fit=crop&w=800&q=70","imageAlt":"حفل عيد ميلاد","usefulPhrases":[{"de":"Hallo Karim,","ar":"مرحباً كريم،"},{"de":"wie geht es dir? Mir geht es super!","ar":"كيف حالك؟ أنا بخير جداً!"},{"de":"am Samstag ist mein Geburtstag und ich feiere zu Hause.","ar":"السبت عيد ميلادي وأحتفل في البيت."},{"de":"Es geht um 19:00 Uhr los.","ar":"يبدأ الحفل الساعة 19."},{"de":"Bring bitte ... mit, wenn du magst.","ar":"أحضر معك... من فضلك."},{"de":"Bitte sag mir Bescheid, ob du kommst.","ar":"أخبرني إذا كنت ستأتي."},{"de":"Ich freue mich riesig auf dich!","ar":"أتطلّع لرؤيتك بشدّة!"}],"sampleAnswerNotes":["استخدم لهجة ودودة \"du\" — دعوة بين أصدقاء.","حدّد التاريخ والوقت بوضوح."],"sampleAnswer":"Hallo Karim,\n\nwie geht's dir? Mir geht es super, denn ich habe großartige Neuigkeiten: Am Samstag, dem 22. März, habe ich endlich Geburtstag! Ich feiere bei mir zu Hause (Hauptstraße 17, 3. Stock).\n\nEs geht um 19:00 Uhr los, und es gibt Pizza, Musik und natürlich Kuchen. Wenn du magst, bring bitte einen Salat oder ein paar Getränke mit – wir teilen das wie immer.\n\nBitte sag mir bis Freitag Bescheid, ob du dabei bist. Ich freue mich riesig, dich zu sehen!\n\nLiebe Grüße,\nLina"}]},{"id":"schreiben-9","title":"نموذج Schreiben رقم 9 — مواقف عمل وسكن","description":"ثلاث مهام: تقديم لتدريب، شكوى للمؤجّر عن العفن، طلب يوم إجازة.","tasks":[{"id":"schreiben-9-1","taskNumber":1,"typeAr":"طلب تدريب (Praktikum) في شركة","typeDe":"Bewerbung um ein Praktikum","promptAr":"رأيت إعلاناً عن تدريب صيفي مدّته 6 أسابيع في شركة هندسة. اكتب رسالة تقديم قصيرة.","promptDe":"Sie haben eine Anzeige für ein 6-wöchiges Sommerpraktikum in einer Ingenieursfirma gesehen. Schreiben Sie eine kurze Bewerbung.","requirements":["اذكر مصدر إعلان التدريب","اشرح من تكون ولماذا أنت مهتمّ","اذكر مهارة أو خبرة سابقة (واحدة)","اطلب موعد مقابلة"],"wordCount":"حوالي 90-100 كلمة","imageUrl":"https://images.unsplash.com/photo-1454165804606-c3d57bc86b40?auto=format&fit=crop&w=800&q=70","imageAlt":"تقديم وظيفة","usefulPhrases":[{"de":"mit großem Interesse habe ich Ihre Anzeige auf ... gelesen.","ar":"قرأت إعلانكم باهتمام كبير على..."},{"de":"hiermit bewerbe ich mich um ein Praktikum als ...","ar":"بهذا أتقدّم لتدريب كـ..."},{"de":"Ich studiere derzeit ... im ... Semester.","ar":"أدرس حالياً... في الفصل..."},{"de":"Besonders interessiert mich Ihr Bereich ...","ar":"يهمّني خصوصاً مجالكم..."},{"de":"Erste Erfahrungen habe ich bereits bei ... gesammelt.","ar":"اكتسبت خبرة أوّليّة في..."},{"de":"Über die Möglichkeit zu einem Vorstellungsgespräch würde ich mich sehr freuen.","ar":"سأكون ممتنّاً لفرصة المقابلة."}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nmit großem Interesse habe ich Ihre Anzeige auf der Website \"Praktikum.info\" gelesen. Hiermit bewerbe ich mich um das ausgeschriebene 6-wöchige Praktikum als Ingenieurassistent.\n\nIch studiere derzeit Maschinenbau im 4. Semester an der TU Berlin und suche eine praktische Erfahrung im Sommer 2025. Besonders interessiert mich Ihr Bereich der erneuerbaren Energien, da ich meine Bachelorarbeit dazu plane.\n\nErste Erfahrungen habe ich bereits in einem 3-monatigen Werkstudentenjob bei einer kleineren Firma gesammelt, wo ich technische Zeichnungen mit AutoCAD erstellt habe.\n\nÜber die Möglichkeit zu einem Vorstellungsgespräch würde ich mich sehr freuen.\n\nMit freundlichen Grüßen,\nTarek Ibrahim"},{"id":"schreiben-9-2","taskNumber":2,"typeAr":"شكوى للمؤجّر عن عفن (Schimmel) في الحمّام","typeDe":"Beschwerde beim Vermieter wegen Schimmel","promptAr":"منذ شهر ظهر عفن (Schimmel) كبير على جدار حمّامك. حاولت الاتّصال بالمؤجّر مرّتين بدون ردّ. اكتب رسالة رسميّة.","promptDe":"Seit einem Monat zeigt sich an Ihrer Badezimmerwand großer Schimmel. Sie haben Ihren Vermieter zweimal angerufen, aber keine Antwort bekommen. Schreiben Sie einen formellen Brief.","requirements":["اذكر عنوان الشقّة وتاريخ ظهور المشكلة","صف العفن بدقّة (مكانه/حجمه)","اذكر المحاولات السابقة للتواصل","اطلب تصليحاً عاجلاً وتلميحاً لتخفيض الإيجار (Mietminderung)"],"wordCount":"حوالي 100-120 كلمة","imageUrl":"https://images.unsplash.com/photo-1564540586988-aa4e53c3d799?auto=format&fit=crop&w=800&q=70","imageAlt":"حمّام","usefulPhrases":[{"de":"hiermit teile ich Ihnen mit, dass ...","ar":"بهذا أبلغكم أنّ..."},{"de":"in der Wohnung ... ist ein erheblicher Mangel aufgetreten.","ar":"في الشقّة... ظهر عيب كبير."},{"de":"an der Wand des Badezimmers hat sich ein großer Schimmelfleck gebildet.","ar":"على جدار الحمّام تكوّنت بقعة عفن كبيرة."},{"de":"der Schimmel breitet sich täglich weiter aus.","ar":"العفن يتمدّد يوميّاً."},{"de":"Ich habe Sie bereits zweimal telefonisch zu erreichen versucht.","ar":"حاولت الاتّصال هاتفيّاً مرّتين بدون نتيجة."},{"de":"Ich fordere Sie auf, den Schaden innerhalb von ... Tagen zu beheben.","ar":"أطالبكم بإصلاح الضرر خلال... يوماً."},{"de":"Andernfalls behalte ich mir eine Mietminderung vor.","ar":"وإلّا فسأحتفظ بحقّ تخفيض الإيجار."}],"sampleAnswer":"Sehr geehrter Herr Müller,\n\nhiermit teile ich Ihnen mit, dass in der von mir gemieteten Wohnung in der Goethestraße 24, 1. Stock, ein erheblicher Mangel aufgetreten ist.\n\nSeit etwa einem Monat hat sich an der Wand des Badezimmers (neben der Dusche) ein großer Schimmelfleck gebildet, der mittlerweile etwa 50×60 cm groß ist und sich täglich weiter ausbreitet. Der Geruch ist sehr unangenehm und ich befürchte gesundheitliche Folgen für meine Familie, besonders für meinen 4-jährigen Sohn.\n\nIch habe Sie bereits am 5. und 12. März telefonisch zu erreichen versucht, leider ohne Erfolg.\n\nIch fordere Sie hiermit schriftlich auf, den Schaden innerhalb von 14 Tagen fachgerecht zu beheben. Andernfalls werde ich eine angemessene Mietminderung von 20% vornehmen, wie es das Mietrecht vorsieht.\n\nMit freundlichen Grüßen,\nFamilie Khaled"},{"id":"schreiben-9-3","taskNumber":3,"typeAr":"طلب يوم إجازة من المدير","typeDe":"Urlaubsantrag beim Chef","promptAr":"تحتاج يوماً إجازة لحضور جلسة مهمّة في Bürgeramt. اكتب رسالة قصيرة لمديرك.","promptDe":"Sie brauchen einen Urlaubstag für einen wichtigen Termin beim Bürgeramt. Schreiben Sie eine kurze E-Mail an Ihren Chef.","requirements":["اشرح الحاجة بإيجاز","حدّد التاريخ المطلوب","اقترح تأجيل/تغطية المهامّ","اطلب الموافقة"],"wordCount":"حوالي 60-70 كلمة","imageUrl":"https://images.unsplash.com/photo-1486312338219-ce68d2c6f44d?auto=format&fit=crop&w=800&q=70","imageAlt":"مكتب","usefulPhrases":[{"de":"Sehr geehrter Herr ... / Sehr geehrte Frau ...,","ar":"سيدي/سيدتي المحترم/ة،"},{"de":"hiermit beantrage ich für den ... einen Tag Urlaub.","ar":"بهذا أطلب يوم إجازة بتاريخ..."},{"de":"der Grund ist ein verbindlicher Termin bei ...","ar":"السبب موعد إلزامي لدى..."},{"de":"Meine Aufgaben werde ich vorher abschließen.","ar":"سأكمل مهامّي قبل ذلك."},{"de":"Frau / Herr ... vertritt mich an diesem Tag.","ar":"السيد/ة... ستغطّي مكاني."},{"de":"Über Ihre Genehmigung wäre ich sehr dankbar.","ar":"سأكون ممتنّاً لموافقتكم."}],"sampleAnswer":"Sehr geehrter Herr Becker,\n\nhiermit beantrage ich für den 28. März einen Tag Urlaub. Der Grund ist ein verbindlicher Termin beim Bürgeramt zur Verlängerung meines Aufenthaltstitels, der nicht verschoben werden kann.\n\nMeine laufenden Aufgaben werde ich vorher vollständig abschließen, und Frau Hoffmann hat zugesagt, dringende E-Mails an diesem Tag zu beantworten.\n\nÜber Ihre Genehmigung wäre ich sehr dankbar.\n\nMit freundlichen Grüßen,\nSara Halabi"}]},{"id":"schreiben-10","title":"Schreiben 10 – التواصل الرقمي","description":"ثلاث مهامّ كتابيّة عن البريد الإلكتروني والتطبيقات الرقميّة.","tasks":[{"id":"schreiben-10-1","taskNumber":1,"typeAr":"بريد لصديق عن مشكلة تقنيّة","typeDe":"E-Mail an einen Freund über ein Technik-Problem","promptAr":"إخوتك يطلبون منك مساعدة. حاسوبك لا يعمل ولا تستطيع تسليم واجب الجامعة. اكتب لصديقك يوسف.","promptDe":"Ihre Geschwister bitten Sie um Hilfe. Ihr Computer funktioniert nicht und Sie können die Uni-Hausaufgabe nicht abgeben. Schreiben Sie an Ihren Freund Yusuf.","requirements":["اشرح المشكلة","اسأل عن مساعدة (هل يمكنك استخدام حاسوبه؟)","حدّد متى تريد المجيء","اطلب الردّ السريع"],"wordCount":"حوالي 80 كلمة","usefulPhrases":[{"de":"Hallo Yusuf, wie geht es dir?","ar":"مرحبا يوسف، كيف حالك؟"},{"de":"Ich habe ein großes Problem.","ar":"عندي مشكلة كبيرة."},{"de":"Mein Computer ist kaputt.","ar":"حاسوبي معطّل."},{"de":"Darf ich heute zu dir kommen und deinen Laptop benutzen?","ar":"هل أستطيع أن آتي اليوم لأستخدم حاسوبك؟"},{"de":"Ich muss die Hausaufgabe bis morgen abgeben.","ar":"يجب أن أسلّم الواجب غداً."},{"de":"Bitte antworte schnell!","ar":"أرجو الردّ سريعاً!"}],"sampleAnswer":"Hallo Yusuf,\n\nich hoffe, dir geht es gut. Ich habe ein großes Problem: Mein Computer funktioniert seit heute Morgen nicht mehr — der Bildschirm bleibt schwarz, auch nach einem Neustart.\n\nDas ist ein Notfall, weil ich bis morgen 18 Uhr meine Hausaufgabe in Informatik abgeben muss. Darf ich heute Abend ab 19 Uhr zu dir kommen und deinen Laptop benutzen? Ich brauche nur 2-3 Stunden, dann bin ich fertig.\n\nBitte antworte mir schnell, am besten per WhatsApp.\n\nVielen Dank im Voraus!\nLiebe Grüße,\nKarim"},{"id":"schreiben-10-2","taskNumber":2,"typeAr":"تقييم منتج اشتريته إلكترونيّاً","typeDe":"Bewertung eines online gekauften Produkts","promptAr":"اشتريت سمّاعة بلوتوث من Amazon لكنّ الجودة سيّئة. اكتب تقييماً موضوعيّاً.","promptDe":"Sie haben einen Bluetooth-Kopfhörer bei Amazon gekauft, aber die Qualität ist schlecht. Schreiben Sie eine sachliche Bewertung.","requirements":["اذكر اسم المنتج وتاريخ الشراء","اشرح ثلاث مشاكل واجهتها","اذكر شيئاً إيجابياً (إن وجد)","وصِ أو لا توصِ بالمنتج للآخرين"],"wordCount":"حوالي 100-120 كلمة","usefulPhrases":[{"de":"Ich habe den Kopfhörer am ... gekauft.","ar":"اشتريت السمّاعة في..."},{"de":"Leider bin ich enttäuscht.","ar":"للأسف أنا مخيّب الأمل."},{"de":"Der Akku hält nur ...","ar":"البطّاريّة تدوم فقط..."},{"de":"Die Soundqualität ist mittelmäßig.","ar":"جودة الصوت متوسّطة."},{"de":"Was mir gut gefällt, ist ...","ar":"ما يعجبني هو..."},{"de":"Ich kann das Produkt nicht weiterempfehlen.","ar":"لا أنصح بهذا المنتج."}],"sampleAnswer":"Bewertung: Bluetooth-Kopfhörer \"SoundPro X3\"\nGekauft am 15. Februar 2026.\n\nLeider bin ich von dem Produkt enttäuscht. Erstens hält der Akku nur 3 Stunden statt der versprochenen 12 Stunden. Zweitens reißt die Bluetooth-Verbindung alle paar Minuten ab, besonders wenn das Handy in der Tasche ist. Drittens ist die Lautstärke zu leise — in der U-Bahn höre ich fast nichts.\n\nWas mir gut gefällt: Das Design ist modern und der Tragekomfort ist gut. Die Kopfhörer drücken nicht auf den Ohren.\n\nInsgesamt kann ich das Produkt nicht empfehlen. Für 49 € hatte ich mehr erwartet. Wer bessere Klangqualität sucht, sollte mehr investieren oder eine andere Marke wählen.\n\nBewertung: 2 von 5 Sternen."},{"id":"schreiben-10-3","taskNumber":3,"typeAr":"طلب الغاء اشتراك إلكتروني","typeDe":"Schriftliche Kündigung eines Online-Abos","promptAr":"تريد إلغاء اشتراك Netflix الذي تدفع فيه 17,99 € شهريّاً. اكتب لخدمة العملاء.","promptDe":"Sie möchten Ihr Netflix-Abo für 17,99 € im Monat kündigen. Schreiben Sie an den Kundenservice.","requirements":["اذكر بياناتك ورقم الاشتراك","اطلب الإلغاء صراحةً","حدّد التاريخ المطلوب للإنهاء","اطلب تأكيداً كتابيّاً"],"wordCount":"حوالي 70 كلمة","usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"سيّداتي سادتي،"},{"de":"hiermit kündige ich mein Abonnement zum nächstmöglichen Termin.","ar":"بهذا ألغي اشتراكي بأقرب فرصة."},{"de":"Meine Kunden-Nummer lautet: ...","ar":"رقم زبوني هو..."},{"de":"Ich bitte um schriftliche Bestätigung.","ar":"أرجو التأكيد كتابيّاً."},{"de":"Bitte stornieren Sie auch zukünftige Abbuchungen.","ar":"أرجو إيقاف الخصومات المستقبليّة."}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nhiermit kündige ich mein Netflix-Abonnement zum nächstmöglichen Termin. Meine Kundennummer lautet 4587-2298-XY und das Abo wird unter der E-Mail kasem@gmail.com geführt.\n\nIch bitte um eine schriftliche Bestätigung mit dem genauen Beendigungsdatum sowie um die Einstellung zukünftiger Abbuchungen von meinem Konto.\n\nMit freundlichen Grüßen,\nMahmoud Kasem"}]},{"id":"schreiben-11","title":"Schreiben 11 – المواقف الرسميّة","description":"مهامّ كتابة رسميّة: شكوى لشركة، طلب موعد، رفض دعوة بأدب.","tasks":[{"id":"schreiben-11-1","taskNumber":1,"typeAr":"شكوى لشركة الكهرباء","typeDe":"Beschwerde beim Stromanbieter","promptAr":"فاتورة الكهرباء عاليّة جدّاً هذا الشهر (350 € بدل 90 €). اكتب شكوى رسميّة.","promptDe":"Ihre Stromrechnung ist in diesem Monat sehr hoch (350 € statt 90 €). Schreiben Sie eine formelle Beschwerde.","requirements":["اذكر رقم الزبون والعداد","اشرح المشكلة بدقّة","اطلب فحص العداد","حدّد مهلة للردّ"],"wordCount":"حوالي 100-120 كلمة","usefulPhrases":[{"de":"Sehr geehrte Damen und Herren,","ar":"سيّداتي سادتي،"},{"de":"mit großem Erstaunen habe ich Ihre Rechnung erhalten.","ar":"باستغراب كبير تلقّيت فاتورتكم."},{"de":"Meine Kundennummer ist ..., der Zählerstand ...","ar":"رقم زبوني... ورقم العدّاد..."},{"de":"Ich kann mir den hohen Betrag nicht erklären.","ar":"لا أستطيع تفسير المبلغ الكبير."},{"de":"Bitte überprüfen Sie den Zähler.","ar":"أرجو فحص العدّاد."},{"de":"Bis zur Klärung bitte ich, die Abbuchung auszusetzen.","ar":"حتّى التوضيح أرجو وقف الخصم."},{"de":"Ich erwarte Ihre Antwort innerhalb von 14 Tagen.","ar":"أنتظر ردّكم خلال 14 يوماً."}],"sampleAnswer":"Sehr geehrte Damen und Herren,\n\nmit großem Erstaunen habe ich Ihre Stromrechnung vom 28. Februar 2026 erhalten. Der Betrag beläuft sich auf 350 €, obwohl meine durchschnittliche Monatsrechnung in den letzten zwölf Monaten zwischen 80 € und 95 € lag.\n\nMeine Kundennummer ist 5847-3290 und der aktuelle Zählerstand 28475 kWh. Mein Verbrauch hat sich in den letzten Monaten nicht verändert — wir sind weiterhin zu dritt im Haushalt, ohne neue Geräte. Eine Verdreifachung der Rechnung ist nicht nachvollziehbar.\n\nBitte überprüfen Sie den Zähler vor Ort und stellen Sie sicher, dass kein Ablesefehler vorliegt. Bis zur endgültigen Klärung bitte ich Sie, die SEPA-Abbuchung auszusetzen.\n\nIch erwarte Ihre schriftliche Antwort innerhalb von 14 Tagen.\n\nMit freundlichen Grüßen,\nAhmad Halabi"},{"id":"schreiben-11-2","taskNumber":2,"typeAr":"طلب موعد لدى الطبيب","typeDe":"Terminanfrage beim Arzt","promptAr":"تعاني من ألم في الظهر منذ أسبوع. اكتب بريداً لعيادة الطبيب لطلب موعد عاجل.","promptDe":"Sie haben seit einer Woche Rückenschmerzen. Schreiben Sie eine E-Mail an die Arztpraxis, um einen dringenden Termin zu bekommen.","requirements":["اذكر اسمك وتاريخ ميلادك","صف الأعراض","اقترح موعداً (مع بدائل)","اذكر شركة التأمين"],"wordCount":"حوالي 80 كلمة","usefulPhrases":[{"de":"Sehr geehrtes Praxisteam,","ar":"فريق العيادة المحترم،"},{"de":"mein Name ist ..., geboren am ...","ar":"اسمي... مولود في..."},{"de":"Ich leide seit ... an starken Schmerzen.","ar":"أعاني منذ... من ألم شديد."},{"de":"Ich bitte um einen baldigen Termin.","ar":"أرجو موعداً قريباً."},{"de":"Ich kann Montag bis Freitag ab 16 Uhr kommen.","ar":"أستطيع من الإثنين للجمعة بعد الـ16."},{"de":"Meine Krankenkasse ist ...","ar":"تأميني الصحي هو..."}],"sampleAnswer":"Sehr geehrtes Praxisteam Dr. Wagner,\n\nmein Name ist Salah Karim, geboren am 12.05.1985. Ich bin Ihr Patient seit 2022.\n\nIch leide seit einer Woche an starken Rückenschmerzen, besonders im unteren Bereich. Auch das Aufstehen morgens fällt mir sehr schwer. Schmerztabletten helfen kaum noch.\n\nIch bitte daher um einen baldigen Termin, am besten in dieser oder nächsten Woche. Ich kann Montag bis Freitag ab 16 Uhr und samstags vormittags kommen.\n\nMeine Krankenkasse ist die AOK.\n\nVielen Dank im Voraus für Ihre Mühe!\n\nMit freundlichen Grüßen,\nSalah Karim"},{"id":"schreiben-11-3","taskNumber":3,"typeAr":"رفض دعوة بأدب","typeDe":"Höfliche Absage einer Einladung","promptAr":"دعتك جارتك السيّدة شميدت لحفلة عيد ميلاد ابنتها. لا تستطيع الحضور. اكتب رسالة قصيرة.","promptDe":"Ihre Nachbarin Frau Schmidt hat Sie zur Geburtstagsfeier ihrer Tochter eingeladen. Sie können nicht kommen. Schreiben Sie eine kurze E-Mail.","requirements":["اشكرها على الدعوة","اذكر السبب باختصار","تمنّ يوماً جميلاً","اقترح موعداً بديلاً للقاء"],"wordCount":"حوالي 60 كلمة","usefulPhrases":[{"de":"Liebe Frau Schmidt,","ar":"عزيزتي السيّدة شميدت،"},{"de":"vielen Dank für Ihre nette Einladung.","ar":"شكراً جزيلاً للدعوة اللطيفة."},{"de":"leider kann ich nicht kommen, weil ...","ar":"للأسف لا أستطيع الحضور لأنّ..."},{"de":"Ich wünsche Ihrer Tochter alles Gute zum Geburtstag.","ar":"أتمنّى لابنتك كلّ التوفيق بعيد ميلادها."},{"de":"Können wir uns nächste Woche auf einen Kaffee treffen?","ar":"هل نستطيع اللقاء الأسبوع القادم على قهوة؟"}],"sampleAnswer":"Liebe Frau Schmidt,\n\nvielen Dank für Ihre nette Einladung zur Geburtstagsfeier von Mia. Leider kann ich nicht kommen, weil ich an diesem Wochenende eine Pflicht-Veranstaltung an der Universität habe, die ich nicht verschieben kann.\n\nBitte richten Sie Mia meine herzlichen Glückwünsche aus! Ich werde ihr ein kleines Geschenk vor die Tür stellen.\n\nVielleicht können wir uns nächste Woche auf einen Kaffee treffen? Donnerstag oder Freitag Nachmittag würde mir passen.\n\nLiebe Grüße,\nLina"}]}]'''));


final List<Map<String, dynamic>> schreibenTemplates = [{'id': 'einladung-geburtstag', 'titleAr': 'دعوة لحفلة عيد ميلاد (غير رسمي)', 'titleDe': 'Einladung zum Geburtstag', 'typ': 'informal', 'scenario': 'تكتب لصديقك تدعوه إلى عيد ميلادك. أخبره عن المكان، الوقت، وما يحضره.', 'punkte': ['مكان الحفل', 'تاريخ ووقت', 'ماذا يحضر معه', 'كيف يصل المكان'], 'body': 'Liebe(r) [Name],\n\nich hoffe, dir geht es gut! Ich wollte dir mitteilen, dass ich am Samstag, den 15. Mai, meinen Geburtstag feiere und du natürlich herzlich eingeladen bist!\n\nDie Feier beginnt um 19 Uhr bei mir zu Hause (Hauptstraße 12, 2. Stock). Es wird Essen und Musik geben. Bring bitte gute Laune mit – Geschenke sind nicht nötig!\n\nWenn du Lust hast, kannst du auch deine Freundin/deinen Freund mitbringen. Sag mir bitte bis Mittwoch Bescheid, ob du kommst, damit ich genug Essen einkaufen kann.\n\nIch freue mich riesig auf dich!\n\nLiebe Grüße,\n[Dein Name]', 'hinweise': ['استخدم ضمير الـ"du" دائماً.', 'اذكر التحية الحارّة في البداية ("Ich hoffe, dir geht es gut!").', 'حدّد جميع التفاصيل: التاريخ، الوقت، العنوان.', 'أنهِ بـ "Liebe Grüße" أو "Viele Grüße".']}, {'id': 'absage-einladung', 'titleAr': 'اعتذار عن دعوة (غير رسمي)', 'titleDe': 'Absage einer Einladung', 'typ': 'informal', 'scenario': 'لا تستطيع الذهاب لحفل صديقك. أخبره بسبب اعتذارك واقترح بديلاً.', 'punkte': ['شكر على الدعوة', 'سبب الاعتذار', 'تعبير عن الأسف', 'اقتراح لقاء آخر'], 'body': 'Lieber [Name],\n\nvielen Dank für deine Einladung! Ich habe mich wirklich sehr gefreut, dass du an mich gedacht hast.\n\nLeider kann ich am Samstag nicht kommen. Meine Schwester aus Syrien besucht mich zum ersten Mal in Deutschland und ich möchte den ganzen Tag mit ihr verbringen. Es tut mir wirklich leid, dass ich nicht dabei sein kann.\n\nIch würde dich aber gerne nächste Woche zum Essen einladen! Hättest du am Sonntag Zeit? Wir könnten ins libanesische Restaurant gehen, das du so magst.\n\nSag mir Bescheid, wann es dir passt.\n\nBis bald,\n[Dein Name]', 'hinweise': ['كن مهذّباً: ابدأ بالشكر على الدعوة.', 'اشرح السبب باختصار وبدون تفاصيل كثيرة.', 'اقترح بديلاً (لقاء آخر) لتظهر اهتمامك بالعلاقة.', 'استخدم "Es tut mir leid, dass..." للاعتذار.']}, {'id': 'forum-internet', 'titleAr': 'مشاركة في منتدى نقاشي', 'titleDe': 'Forumsbeitrag', 'typ': 'forum', 'scenario': 'منتدى يناقش "هل التسوق عبر الإنترنت أفضل من السوق التقليدي؟" اكتب رأيك بـ80 كلمة.', 'punkte': ['عرض رأيك بوضوح', 'ذكر مزايا/عيوب', 'مثال شخصي', 'استنتاج'], 'body': 'Liebes Forum,\n\nich finde dieses Thema sehr interessant und möchte gerne meine Meinung dazu äußern.\n\nIch kaufe persönlich gerne im Internet ein, weil es so viele Vorteile gibt. Erstens spart man sehr viel Zeit, weil man nicht in den Laden fahren muss. Zweitens sind die Preise oft günstiger und man kann verschiedene Anbieter leicht vergleichen.\n\nAllerdings hat das Online-Shopping auch Nachteile. Man kann die Produkte nicht anprobieren oder anfassen. Außerdem ist es nicht gut für die Umwelt, weil viele Pakete verschickt werden.\n\nMeiner Meinung nach ist eine Mischung am besten: Lebensmittel im Geschäft, Bücher und Kleidung online.\n\nViele Grüße,\n[Nutzername]', 'hinweise': ['ابدأ بـ "Liebes Forum".', 'استخدم روابط مثل "Erstens... Zweitens... Allerdings...".', 'قدّم رأيك الشخصي بوضوح ("Meiner Meinung nach...").', 'اختم بـ "Viele Grüße".']}, {'id': 'forum-handy', 'titleAr': 'مشاركة في منتدى عن الموبايل', 'titleDe': 'Forumsbeitrag – Handy in der Schule', 'typ': 'forum', 'scenario': 'منتدى يناقش "هل يجب السماح للطلاب باستخدام الموبايل في المدرسة؟" اكتب رأيك.', 'punkte': ['موقفك الواضح', 'سببان على الأقل', 'مثال', 'الاستنتاج'], 'body': 'Liebes Forum,\n\ndas Thema "Handys in der Schule" finde ich sehr aktuell und wichtig. Meine Meinung dazu möchte ich gerne mit euch teilen.\n\nIch bin der Meinung, dass Handys in der Schule **nicht** erlaubt sein sollten. Erstens lenken sie die Schüler vom Unterricht ab. Wenn jemand eine Nachricht bekommt, kann er sich nicht mehr konzentrieren. Zweitens benutzen viele Schüler das Handy zum Schummeln bei Tests.\n\nAllerdings kann das Handy in Notfällen sehr nützlich sein, zum Beispiel um die Eltern anzurufen. Deshalb finde ich, dass die Schüler ihre Handys während des Unterrichts ausschalten und sie nur in den Pausen benutzen sollten.\n\nSo lernen sie auch, verantwortungsvoll mit Technik umzugehen.\n\nViele Grüße,\n[Nutzername]', 'hinweise': ['موقف واضح + سببان على الأقل.', 'استخدم "Erstens... Zweitens... Allerdings... Deshalb...".', 'قدّم حلاً وسطاً (Kompromiss) – يعجب القارئ.']}, {'id': 'beschwerde-nachbar', 'titleAr': 'شكوى لإدارة العقار من جار مزعج (رسمي)', 'titleDe': 'Beschwerde wegen lautem Nachbarn', 'typ': 'beschwerde', 'scenario': 'تكتب لإدارة المبنى تشتكي من جار يصدر ضوضاء عالية ليلاً. اطلب اتخاذ إجراء.', 'punkte': ['وصف المشكلة', 'متى وكيف تحدث', 'أثرها عليك', 'طلب واضح', 'مهلة للرد'], 'body': 'Sehr geehrte Damen und Herren,\n\nmein Name ist [Vor- und Nachname] und ich wohne seit zwei Jahren in der Wohnung Nr. 3 in der Hauptstraße 12. Ich schreibe Ihnen, weil ich ein ernstes Problem mit meinem Nachbarn aus Wohnung Nr. 4 habe.\n\nSeit etwa drei Monaten hört mein Nachbar fast jede Nacht laute Musik bis nach 1 Uhr morgens. Außerdem feiert er regelmäßig am Wochenende mit vielen Gästen. Der Lärm ist so stark, dass ich und meine Familie nicht schlafen können. Wir sind morgens immer müde und meine Kinder können in der Schule nicht aufpassen.\n\nIch habe schon mehrmals freundlich mit ihm gesprochen, leider ohne Erfolg. Deshalb bitte ich Sie höflich, mit ihm Kontakt aufzunehmen und auf die Hausordnung hinzuweisen.\n\nIch erwarte Ihre Antwort innerhalb von zwei Wochen. Vielen Dank im Voraus für Ihre Hilfe.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]', 'hinweise': ['✓ "Sehr geehrte Damen und Herren" في البداية، "Mit freundlichen Grüßen" في النهاية.', '✓ اذكر اسمك ورقم شقّتك.', '✓ صف المشكلة بدقّة (متى، كم مرّة، ما تأثيرها).', '✓ اذكر أنك حاولت الحلّ ودّياً قبل الشكوى.', '✓ اطلب إجراءً محدّداً ضمن مهلة.']}, {'id': 'kuendigung-vertrag', 'titleAr': 'إلغاء اشتراك (رسمي)', 'titleDe': 'Vertragskündigung (Fitnessstudio/Handy)', 'typ': 'formal', 'scenario': 'تريد إلغاء اشتراكك في النادي الرياضي. اكتب رسالة رسمية تطلب فيها الإلغاء.', 'punkte': ['بيانات العقد', 'تاريخ الإلغاء', 'سبب اختياري', 'تأكيد كتابي'], 'body': 'Sehr geehrte Damen und Herren,\n\nmein Name ist [Vor- und Nachname], geboren am [Geburtsdatum], und meine Mitgliedsnummer lautet [Nummer]. Mit diesem Schreiben möchte ich meinen Vertrag mit dem Fitnessstudio "Aktiv-Fit" zum nächstmöglichen Termin kündigen.\n\nBitte berücksichtigen Sie die geltende Kündigungsfrist und teilen Sie mir den genauen Beendigungstermin schriftlich mit. Sollte mein Konto vor diesem Datum noch belastet werden, bitte ich um Rückerstattung.\n\nBitte bestätigen Sie mir den Erhalt dieser Kündigung schriftlich.\n\nVielen Dank im Voraus.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]\n[Adresse]\n[Datum]', 'hinweise': ['اذكر بياناتك الكاملة ورقم العضوية.', 'اطلب التأكيد الكتابي ("schriftlich bestätigen").', 'اطلب إلغاء أي خصومات مستقبلية.', 'وقّع باسمك الكامل والعنوان والتاريخ.']}, {'id': 'krankmeldung', 'titleAr': 'إخطار غياب عن العمل بسبب مرض (رسمي)', 'titleDe': 'Krankmeldung an den Arbeitgeber', 'typ': 'formal', 'scenario': 'مرضت ولا تستطيع الذهاب للعمل. اكتب لمديرك تخبره وتعتذر.', 'punkte': ['الاعتذار', 'سبب الغياب', 'مدّة الغياب', 'ذكر الـ Krankenschein'], 'body': 'Sehr geehrte/r Frau/Herr [Name],\n\nleider muss ich Ihnen mitteilen, dass ich heute krank bin und nicht zur Arbeit kommen kann. Ich habe seit gestern Abend hohes Fieber und starke Kopfschmerzen.\n\nIch war heute Morgen beim Arzt und er hat mich für drei Tage krankgeschrieben. Den Krankenschein werde ich Ihnen so schnell wie möglich zukommen lassen.\n\nIch hoffe, dass ich am Donnerstag wieder zur Arbeit kommen kann. Sollten dringende Aufgaben anstehen, können Sie mich gerne per E-Mail erreichen.\n\nVielen Dank für Ihr Verständnis.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]', 'hinweise': ['أرسل الرسالة في **أقرب وقت ممكن** (في يوم المرض).', 'اذكر مدّة الغياب المتوقّعة بدقّة.', 'وعد بإرسال الـ Krankenschein.', 'اعرض إمكانية الاتصال بك للأمور العاجلة.']}, {'id': 'umzug-information', 'titleAr': 'إخطار صديق بالانتقال إلى مدينة جديدة (غير رسمي)', 'titleDe': 'Umzug ankündigen', 'typ': 'informal', 'scenario': 'انتقلت إلى مدينة جديدة. اكتب لصديقك تخبره عن المدينة الجديدة وادعه للزيارة.', 'punkte': ['سبب الانتقال', 'وصف المدينة الجديدة', 'الشقة الجديدة', 'دعوة للزيارة'], 'body': 'Liebe(r) [Name],\n\nes ist schon eine Weile her, seit wir uns gesehen haben! Ich habe eine große Neuigkeit: Ich bin letzten Monat nach München umgezogen!\n\nDer Grund war eine neue Arbeitsstelle bei einer großen Firma. Die Stadt gefällt mir wirklich sehr gut. Sie ist sauber, hat viele Parks und das öffentliche Verkehrsnetz funktioniert hervorragend. Mein Apartment ist klein (ca. 45 m²), aber sehr gemütlich und liegt nur 10 Minuten vom Marienplatz entfernt.\n\nIch würde mich riesig freuen, wenn du mich besuchen kommst! Wir könnten zusammen die Altstadt erkunden, in einem Biergarten essen und vielleicht sogar ins Schloss Nymphenburg fahren.\n\nWann hättest du Zeit? Sag mir Bescheid und ich plane alles!\n\nBis bald,\n[Dein Name]', 'hinweise': ['ابدأ بتذكير ودّي بأنّك لم تتواصل معه منذ فترة.', 'صف المدينة بـ 3-4 جمل (ميزات).', 'ادعُه بحماس واقترح أنشطة محدّدة.']}, {'id': 'bewerbung-stelle', 'titleAr': 'طلب توظيف (Anschreiben رسمي)', 'titleDe': 'Bewerbungsschreiben', 'typ': 'formal', 'scenario': 'تقدّم على وظيفة قرأت إعلانها في الإنترنت.', 'punkte': ['الإشارة إلى الإعلان', 'مَن أنت', 'خبراتك', 'لماذا أنت الأنسب', 'الدعوة لمقابلة'], 'body': 'Sehr geehrte Damen und Herren,\n\nmit großem Interesse habe ich Ihre Stellenanzeige im Internetportal "Stellenmarkt.de" gelesen und bewerbe mich hiermit um die Stelle als [Berufsbezeichnung] in Ihrem Unternehmen.\n\nIch bin [Alter] Jahre alt, komme ursprünglich aus Syrien und lebe seit [X] Jahren in Deutschland. Mein Sprachniveau in Deutsch ist B1. Vor meiner Ankunft in Deutschland habe ich [X] Jahre als [Beruf] gearbeitet. Hier in Deutschland habe ich bereits einen Praktikumsplatz bei [Firma] absolviert, wo ich [Erfahrung] gesammelt habe.\n\nIch bin pünktlich, lerne schnell und arbeite gerne im Team. Außerdem bin ich motiviert, mich weiterzubilden und im Beruf zu wachsen.\n\nÜber die Möglichkeit eines persönlichen Vorstellungsgesprächs würde ich mich sehr freuen.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]\n[Adresse]\n[Telefon] | [E-Mail]', 'hinweise': ['استخدم "mit großem Interesse" في البداية – عبارة قياسية.', 'اذكر مصدر الإعلان بدقّة.', 'ركّز على ميزاتك (pünktlich, motiviert, lernbereit).', 'اطلب مقابلة شخصية في النهاية.']}, {'id': 'reklamation-ware', 'titleAr': 'شكوى من بضاعة معطوبة (رسمي)', 'titleDe': 'Reklamation defekter Ware', 'typ': 'beschwerde', 'scenario': 'اشتريت جهازاً عبر الإنترنت، وصلك معطوباً. اكتب طلب استبدال أو استرداد.', 'punkte': ['تاريخ الشراء ورقم الطلب', 'وصف العيب', 'ما تطلبه', 'مهلة الرد'], 'body': 'Sehr geehrte Damen und Herren,\n\nam [Datum] habe ich bei Ihnen einen [Produkt, z. B. Wasserkocher, Modell ABC-123] bestellt (Bestellnummer: [Nummer]). Heute ist die Ware angekommen, aber leider ist sie defekt.\n\nGenauer gesagt: Das Gerät schaltet sich nach wenigen Sekunden automatisch aus und das Display zeigt eine Fehlermeldung. Ich habe es laut Anleitung mehrmals ausprobiert, leider ohne Erfolg.\n\nIch möchte Sie daher bitten, mir entweder ein neues, funktionierendes Gerät zuzuschicken oder mir den Kaufpreis zurückzuerstatten. Den Kassenbon und Fotos des Defekts habe ich dieser E-Mail als Anhang beigefügt.\n\nIch erwarte Ihre Antwort innerhalb einer Woche.\n\nVielen Dank im Voraus.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]', 'hinweise': ['اذكر تاريخ الطلب ورقمه بدقّة.', 'صف العيب بوضوح (ما يحدث؟ متى؟).', 'اذكر أنك جرّبت الحلول قبل الشكوى.', 'اطلب بديلاً واضحاً (استبدال أو استرداد).', 'اذكر المرفقات (إيصال، صور).']}, {'id': 'wohnungsanfrage', 'titleAr': 'استفسار عن شقّة للإيجار (رسمي)', 'titleDe': 'Wohnungsanfrage', 'typ': 'formal', 'scenario': 'رأيت إعلان شقة على الإنترنت. اكتب طلباً لمشاهدتها.', 'punkte': ['الإشارة إلى الإعلان', 'مَن أنت ومَن سيعيش معك', 'مهنتك ودخلك', 'طلب موعد', 'تأكيد على وثائقك'], 'body': 'Sehr geehrte Damen und Herren,\n\nmit großem Interesse habe ich Ihre Anzeige für die 2-Zimmer-Wohnung in der [Adresse] auf [Portal] gelesen und ich würde sie gerne besichtigen.\n\nMein Name ist [Vor- und Nachname], ich bin [Alter] Jahre alt und arbeite als [Beruf] bei [Firma]. Mein Nettoeinkommen beträgt monatlich etwa [Betrag] Euro. Ich würde mit meiner Frau und unserem Kind in die Wohnung einziehen.\n\nWir sind nicht-rauchend, ohne Haustiere und sehr ruhig. Eine Schufa-Auskunft, Gehaltsnachweise und eine Mietschuldenfreiheitsbescheinigung kann ich gerne bei einer Besichtigung vorlegen.\n\nHätten Sie nächste Woche einen Termin frei? Ich bin zeitlich sehr flexibel.\n\nVielen Dank für Ihre Mühe und ich freue mich auf Ihre Antwort.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]', 'hinweise': ['الإسكان مهم: قدّم نفسك بإيجاز ومهنياً.', 'اذكر الدخل الصافي (Nettoeinkommen) – أصحاب العقارات يطلبون ذلك.', 'وثائق مهمة: Schufa, Gehaltsnachweise, Mietschuldenfreiheit.', 'كن مرناً في المواعيد.']}, {'id': 'termin-bewerbung-ausbildung', 'titleAr': 'طلب موعد لمقابلة في Ausländerbehörde (رسمي)', 'titleDe': 'Terminanfrage Ausländerbehörde', 'typ': 'formal', 'scenario': 'تحتاج موعداً لتجديد إقامتك (Aufenthaltstitel).', 'punkte': ['سبب الموعد', 'بياناتك', 'مرونتك في الوقت', 'الوثائق التي ستحضرها'], 'body': 'Sehr geehrte Damen und Herren,\n\nmein Name ist [Vor- und Nachname], geboren am [Geburtsdatum], und ich bin syrische(r) Staatsangehörige(r). Ich wende mich an Sie mit der Bitte um einen Termin zur Verlängerung meines Aufenthaltstitels.\n\nMein aktueller Aufenthaltstitel läuft am [Datum] ab. Aus diesem Grund möchte ich rechtzeitig einen Termin bei Ihnen vereinbaren, um eine Verlängerung zu beantragen.\n\nIch bin zeitlich flexibel und kann jeden Wochentag zwischen 9:00 und 16:00 Uhr kommen. Selbstverständlich bringe ich alle erforderlichen Unterlagen mit (Pass, Meldebescheinigung, Krankenversicherungsnachweis, Einkommensnachweis).\n\nBitte teilen Sie mir per E-Mail oder Post einen passenden Termin mit.\n\nVielen Dank für Ihre Mühe.\n\nMit freundlichen Grüßen,\n[Vor- und Nachname]\n[Adresse]\n[Telefon] | [E-Mail]', 'hinweise': ['استخدم اللغة الرسمية بشدّة – هذه جهة رسمية.', 'اذكر تاريخ انتهاء إقامتك بدقّة.', 'اذكر أنّك مرن في الأوقات.', 'عدّد الوثائق التي ستحضرها (يحبّون ذلك).']}, {'id': 'forum-umwelt', 'titleAr': 'مشاركة في منتدى حول البيئة', 'titleDe': 'Forum – Umweltschutz', 'typ': 'forum', 'scenario': 'منتدى يناقش "كيف يمكن للفرد أن يحمي البيئة؟" قدّم 3 أفكار من حياتك.', 'punkte': ['تأكيد أهمية البيئة', '3 إجراءات شخصية', 'مثال', 'استنتاج'], 'body': 'Liebes Forum,\n\nich finde den Umweltschutz heute wichtiger denn je. Wir alle können etwas dafür tun – und zwar jeden Tag!\n\nErstens versuche ich, weniger Plastik zu kaufen. Zum Beispiel benutze ich beim Einkaufen immer eine Stofftasche statt einer Plastiktüte. Zweitens fahre ich kurze Strecken mit dem Fahrrad statt mit dem Auto. Das spart nicht nur CO₂, sondern hält mich auch fit. Drittens trenne ich konsequent meinen Müll und werfe Papier, Plastik und Glas in die richtigen Tonnen.\n\nNatürlich kann eine einzelne Person das Klima nicht alleine retten. Aber wenn jeder von uns ein bisschen mitmacht, machen wir gemeinsam einen großen Unterschied.\n\nWas macht ihr für die Umwelt? Ich freue mich auf eure Antworten!\n\nViele Grüße,\n[Nutzername]', 'hinweise': ['اذكر 3 إجراءات شخصية ملموسة.', 'استخدم "Erstens... Zweitens... Drittens".', 'انهِ بسؤال مفتوح للمجتمع.']}, {'id': 'bedanken-hilfe', 'titleAr': 'شكر شخصاً ساعدك (غير رسمي)', 'titleDe': 'Sich bedanken', 'typ': 'informal', 'scenario': 'صديقك ساعدك في الانتقال للشقّة الجديدة. اكتب له لتشكره وتقترح ردّ المعروف.', 'punkte': ['الشكر بحرارة', 'لماذا كانت مساعدته مهمّة', 'اقتراح ردّ المعروف', 'دعوة للقاء'], 'body': 'Lieber [Name],\n\nich wollte mich noch einmal von Herzen bei dir bedanken! Ohne deine Hilfe beim Umzug am Samstag hätte ich es niemals geschafft.\n\nEs war wirklich nett von dir, dass du den ganzen Tag mit dem Auto gefahren bist und so viele schwere Kartons getragen hast. Und das, obwohl du selbst eine anstrengende Woche hattest!\n\nAls kleines Dankeschön möchte ich dich nächsten Samstag zum Abendessen einladen. Ich koche dir mein bestes syrisches Gericht – natürlich mit deinen Lieblingszutaten! Sag mir Bescheid, ob das für dich passt.\n\nBis bald,\n[Dein Name]', 'hinweise': ['الشكر بصدق وبتفصيل (مَن، متى، ماذا).', 'اقترح ردّ المعروف بطريقة شخصية.', 'انهِ بـ "Bis bald" أو "Liebe Grüße".']}, {'id': 'beschwerde-hotel', 'titleAr': 'شكوى من فندق سيّئ (رسمي)', 'titleDe': 'Beschwerde an ein Hotel', 'typ': 'beschwerde', 'scenario': 'قضيت إجازة في فندق وكانت الخدمة سيّئة (غرفة غير نظيفة، ضوضاء، وعد لم يُنفّذ). تكتب للإدارة تطلب استرداداً جزئياً.', 'punkte': ['تفاصيل الحجز (التاريخ، رقم الحجز)', 'وصف المشاكل بدقّة', 'اقتباسات من العرض/الوعد', 'طلب الاسترداد أو التعويض'], 'body': 'Sehr geehrte Damen und Herren,\n\nvom 10. bis 15. August 2025 habe ich mit meiner Familie in Ihrem Hotel „Sonnenblick" gewohnt (Buchungsnummer: 2025-08745). Leider muss ich mich über mehrere Probleme beschweren.\n\nErstens war das Zimmer bei unserer Ankunft nicht sauber: die Bettwäsche war nicht gewechselt und im Bad fehlten Handtücher. Zweitens wurde uns auf Ihrer Webseite ein Meerblick versprochen, aber wir sahen nur die Parkplatzrückseite. Drittens gab es jede Nacht laute Musik aus der Hotelbar bis 02 Uhr, obwohl im Prospekt „ruhige Lage" steht.\n\nIch bitte Sie um eine teilweise Rückerstattung in Höhe von 30 % des Gesamtpreises sowie um eine schriftliche Stellungnahme. Sollte ich bis zum 15.09.2025 keine Antwort erhalten, werde ich den Fall an die Verbraucherzentrale weiterleiten.\n\nMit freundlichen Grüßen,\n[Ihr Name]\n[Anschrift, Telefon, E-Mail]', 'hinweise': ['اذكر رقم الحجز وتواريخ الإقامة.', 'استشهد بوعود الموقع/البروشور لإثبات حقّك.', 'حدّد التعويض المطلوب بنسبة أو مبلغ.', 'أعطِ مهلة نهائية ("bis zum ...") وتهديد خفيف بالإبلاغ لـ Verbraucherzentrale.']}, {'id': 'beschwerde-produkt', 'titleAr': 'شكوى من منتج معيب (رسمي)', 'titleDe': 'Reklamation eines defekten Produkts', 'typ': 'beschwerde', 'scenario': 'اشتريت جهازاً إلكترونياً (غسّالة / هاتف / لابتوب) ووصلك معيباً أو توقّف بسرعة. تطلب استبداله أو استرداد المال.', 'punkte': ['اسم المنتج + تاريخ الشراء', 'رقم الفاتورة / الطلبية', 'وصف المشكلة', 'طلب الحل (استبدال/إصلاح/استرداد)'], 'body': 'Sehr geehrte Damen und Herren,\n\nam 03.07.2025 habe ich in Ihrem Online-Shop eine Waschmaschine „EcoWash 2000" gekauft (Bestellnummer: 123456). Nach nur zwei Wochen hat das Gerät einen lauten Brummton bekommen, das Programm „Baumwolle 60°" funktioniert gar nicht mehr.\n\nDa die gesetzliche Gewährleistung (2 Jahre) und die Herstellergarantie gelten, bitte ich Sie, das Gerät innerhalb der nächsten 14 Tage kostenlos zu reparieren oder durch ein neues zu ersetzen. Sollten Sie keine Lösung anbieten können, trete ich vom Kaufvertrag zurück und bitte um die volle Rückerstattung von 549 €.\n\nDie Rechnung und Fotos des Schadens liegen als Anlage bei. Ich erwarte Ihre Antwort bis zum 31.07.2025.\n\nMit freundlichen Grüßen,\n[Ihr Name]\n[Anschrift]', 'hinweise': ['اذكر رقم الطلبية وتاريخ الشراء.', 'استخدم "Gewährleistung" (الضمان القانوني) + "Garantie" (ضمان الشركة).', 'اذكر الخيارات بالتدريج: إصلاح → استبدال → استرداد (Rücktritt).', 'ارفق نسخة الفاتورة و (إن أمكن) صور الضرر.']}, {'id': 'beschwerde-dienstleistung', 'titleAr': 'شكوى من خدمة (هاتف/إنترنت/كهرباء)', 'titleDe': 'Beschwerde an einen Dienstleister', 'typ': 'beschwerde', 'scenario': 'تدفع شهرياً لخدمة إنترنت/هاتف لكنها تتعطّل باستمرار. تكتب للشركة تطلب حلاً أو خفض الفاتورة.', 'punkte': ['تفاصيل العقد (رقم الزبون)', 'مدّة وطبيعة العطل', 'محاولات سابقة لحلّه', 'المطلوب (خصم، إلغاء، إصلاح)'], 'body': 'Sehr geehrte Damen und Herren,\n\nals Kunde Ihrer Firma (Kundennummer: 987654321) möchte ich mich hiermit offiziell über die wiederholten Störungen meines Internetanschlusses beschweren.\n\nSeit dem 01.06.2025 ist meine Verbindung fast täglich für mehrere Stunden unterbrochen. Ich habe bereits dreimal bei Ihrer Hotline angerufen (zuletzt am 20.06. unter Ticket-Nr. T-556712), aber die versprochene Techniker-Überprüfung hat bis heute nicht stattgefunden.\n\nIch fordere Sie auf:\n1. Innerhalb von 10 Tagen einen Techniker zu schicken.\n2. Die Monatsgebühr für Juni zu erstatten (Minderung gemäß § 57 TKG).\n3. Mir schriftlich zu bestätigen, wann das Problem behoben ist.\n\nBei weiterer Untätigkeit werde ich den Vertrag außerordentlich kündigen.\n\nMit freundlichen Grüßen,\n[Ihr Name]', 'hinweise': ['اذكر رقم الزبون ورقم التذكرة (Ticket-Nr.).', 'استشهد بالقانون (§ 57 TKG للإنترنت) يزيد من قوة الرسالة.', 'قسّم المطالب في نقاط مرقّمة.', 'هدّد بالإلغاء الاستثنائي (außerordentliche Kündigung) كخيار أخير.']}, {'id': 'beschwerde-nachbar-laerm', 'titleAr': 'شكوى من جار يُصدر ضوضاء (رسمي مهذّب)', 'titleDe': 'Nachbarschaftsbeschwerde (Lärm)', 'typ': 'beschwerde', 'scenario': 'جارك يُصدر ضوضاء متواصلة ليلاً. تكتب له رسالة مهذّبة قبل اللجوء لإدارة البناء.', 'punkte': ['تعريف بنفسك', 'وصف الإزعاج بدقّة', 'ذكر الأوقات الرسمية', 'طلب الحل وديّاً'], 'body': 'Sehr geehrte Familie [Name],\n\nich bin Ihr Nachbar aus der Wohnung Nr. [X] und wollte mich zuerst einmal höflich vorstellen.\n\nIn den letzten Wochen habe ich abends oft sehr laute Musik und Stimmen aus Ihrer Wohnung gehört – leider auch nach 22 Uhr, wenn in Deutschland die Nachtruhe gilt. Ich selbst arbeite früh am Morgen und kann dann kaum schlafen.\n\nIch möchte keinen Streit, sondern nur freundlich bitten: Könnten Sie bitte die Musik nach 22 Uhr leiser stellen? Vielleicht hören wir die Geräusche auch nur, weil die Wände sehr dünn sind.\n\nSollten wir keine Lösung finden, werde ich leider gezwungen sein, die Hausverwaltung zu informieren – das möchte ich aber gerne vermeiden.\n\nMit freundlichen Grüßen und in der Hoffnung auf gutes Miteinander,\n[Ihr Name], Wohnung [Nr.]', 'hinweise': ['ابدأ بتعريف هادئ ومهذّب.', 'اذكر الساعة 22 (Nachtruhe في ألمانيا).', 'أكّد أنك لا تريد خلافاً.', 'اذكر إبلاغ Hausverwaltung كخيار أخير (ليس تهديداً مباشراً).']}, {'id': 'einladung-hochzeit', 'titleAr': 'دعوة لحضور حفل زفاف (غير رسمي)', 'titleDe': 'Einladung zur Hochzeit', 'typ': 'informal', 'scenario': 'تتزوّج قريباً وتريد دعوة صديقك للحفلة.', 'punkte': ['موعد ومكان الحفل', 'موعد الحفل الرسمي (Standesamt) والاحتفال', 'قواعد اللباس', 'موعد التأكيد (RSVP)'], 'body': 'Liebe [Name],\n\nich habe wunderbare Nachrichten! Maria und ich heiraten am Samstag, den 12. September 2025, und wir möchten dich unbedingt dabei haben!\n\nDie standesamtliche Trauung findet um 11 Uhr im Standesamt Berlin-Mitte (Parochialstraße 1) statt. Danach feiern wir ab 15 Uhr im Restaurant „Al-Shamiyyah" (Sonnenallee 45). Es wird Essen, Musik und Tanz geben!\n\nDresscode ist elegant, aber nicht streng formal. Wenn du jemanden mitbringen möchtest, gib mir Bescheid. Über kleine Geschenke freuen wir uns – aber am wichtigsten ist, dass du kommst!\n\nBitte sag uns bis zum 15. August Bescheid, ob du kommen kannst.\n\nWir freuen uns riesig!\n\nLiebe Grüße,\nAhmad & Maria', 'hinweise': ['اذكر التاريخ والساعة وكل مكان بوضوح.', 'اذكر Dresscode إذا كان مهمّاً.', 'حدّد موعد التأكيد (RSVP).', 'استخدم نبرة دافئة واحتفالية.']}, {'id': 'einladung-abendessen', 'titleAr': 'دعوة لعشاء عائلي (غير رسمي)', 'titleDe': 'Einladung zum Abendessen', 'typ': 'informal', 'scenario': 'تريد أن تدعو زملاءك/أصدقاءك إلى عشاء في بيتك.', 'punkte': ['موعد العشاء', 'ماذا ستقدّم', 'ما يحضره الضيف (اختياري)', 'العنوان'], 'body': 'Liebe Freunde,\n\nwie wäre es mit einem gemütlichen syrischen Abendessen bei mir zu Hause? Ich würde mich sehr freuen, wenn ihr am Freitag, den 25. Oktober, um 19 Uhr kommen könntet.\n\nIch werde Kibbeh, Fattoush und Baklava machen – also lasst euch überraschen! 🍽️ Wenn jemand Lust hat, kann er gern einen Nachtisch oder ein Getränk mitbringen, aber es ist wirklich nicht nötig.\n\nMeine Adresse: Hauptstraße 78, 2. Stock, Berlin-Neukölln. Der Aufzug ist leider kaputt, aber es sind nur zwei Stockwerke 🙂.\n\nBitte gebt mir bis Mittwoch Bescheid, damit ich genug einkaufen kann. Ich freue mich schon jetzt auf einen schönen Abend mit euch!\n\nLiebe Grüße,\n[Dein Name]', 'hinweise': ['اذكر ما ستقدّمه ليحفّز الضيوف.', 'اعرض "mitbringen ist nicht nötig" (لا يلزم إحضار شيء).', 'اذكر تفاصيل عملية (المصعد/الموقع).', 'استخدم الإيموجي بحذر للنبرة الودّية.']}, {'id': 'einladung-reise', 'titleAr': 'اقتراح رحلة مع صديق (غير رسمي)', 'titleDe': 'Vorschlag für eine Reise mit Freund/in', 'typ': 'informal', 'scenario': 'تريد أن تقترح على صديقك رحلة نهاية أسبوع معاً.', 'punkte': ['الوجهة', 'التواريخ', 'التكاليف التقديرية', 'سؤال عن رأيه واقتراحاته'], 'body': 'Hallo [Name],\n\nich habe eine tolle Idee! Was hältst du davon, wenn wir zusammen ein Wochenende nach München fahren? Ich war noch nie dort und würde gern die Stadt mit dir erkunden.\n\nIch habe schon einen Zug am Freitag, den 15. November, um 18 Uhr gefunden – die Fahrt kostet mit BahnCard nur 49 € pro Person. Wir könnten in einer günstigen Jugendherberge in der Nähe des Hauptbahnhofs übernachten (ca. 35 € pro Nacht).\n\nWas wir machen könnten:\n• Samstag: Marienplatz, Englischer Garten, Biergarten\n• Sonntag: Deutsches Museum oder Schloss Nymphenburg\n\nWas meinst du? Hast du Lust? Wenn ja, buche ich die Tickets gleich diese Woche. Schreib mir bitte so bald wie möglich!\n\nBis bald,\n[Dein Name]', 'hinweise': ['ابدأ بسؤال مشوّق ("Was hältst du davon …").', 'اذكر تقدير التكاليف ليسهل القرار.', 'اقترح خطّة مرنة (نقاط).', 'اطلب التأكيد بسرعة لتسمح بالحجز.']}, {'id': 'hotel-anfrage', 'titleAr': 'استفسار عن غرفة فندق (رسمي)', 'titleDe': 'Zimmeranfrage bei einem Hotel', 'typ': 'formal', 'scenario': 'تريد حجز غرفة فندقية في مدينة ألمانية وترسل للفندق للاستفسار.', 'punkte': ['تواريخ الإقامة', 'عدد الأشخاص', 'نوع الغرفة', 'خدمات (فطور، واي فاي)'], 'body': 'Sehr geehrte Damen und Herren,\n\nich plane einen Urlaub in Ihrer schönen Stadt und interessiere mich für Ihr Hotel.\n\nKönnten Sie mir bitte mitteilen, ob Sie vom 12. bis 16. Dezember 2025 ein Doppelzimmer mit Frühstück für zwei Erwachsene zur Verfügung haben? Zusätzlich hätte ich folgende Fragen:\n\n1. Wie hoch ist der Preis pro Nacht (inkl. Frühstück)?\n2. Ist WLAN im Zimmer kostenlos?\n3. Gibt es einen Parkplatz oder eine Garage?\n4. Kann ich kurzfristig kostenlos stornieren?\n\nIch freue mich auf Ihre Rückmeldung und bedanke mich im Voraus.\n\nMit freundlichen Grüßen,\n[Ihr Name]\n[E-Mail, Telefonnummer]', 'hinweise': ['اذكر التواريخ وعدد الأشخاص بوضوح.', 'اطرح أسئلة مرقّمة ليسهل الرد.', 'اسأل عن سياسة الإلغاء (kostenlos stornieren) — مهمّة!', 'أنهِ بـ Dank im Voraus و Mit freundlichen Grüßen.']}, {'id': 'mietauto-anfrage', 'titleAr': 'استفسار عن تأجير سيارة (رسمي)', 'titleDe': 'Anfrage zur Autovermietung', 'typ': 'formal', 'scenario': 'تريد استئجار سيارة لرحلة وتسأل شركة التأجير عن الشروط.', 'punkte': ['فترة التأجير', 'فئة السيارة', 'رخصة القيادة والعمر', 'التأمين'], 'body': 'Sehr geehrte Damen und Herren,\n\nich plane eine Reise durch Deutschland vom 20. bis 28. November 2025 und möchte bei Ihnen ein Auto mieten. Dazu hätte ich einige Fragen:\n\n1. Welche Kompaktwagen (z. B. VW Polo, Opel Corsa) sind in diesem Zeitraum verfügbar und was kosten sie pro Tag?\n2. Welche Dokumente brauche ich? (Ich habe einen deutschen Führerschein und bin 28 Jahre alt.)\n3. Ist eine Vollkaskoversicherung im Preis enthalten?\n4. Gibt es eine Kilometerbegrenzung oder sind die Kilometer frei?\n5. Wo kann ich das Auto abholen und zurückgeben (auch außerhalb der Öffnungszeiten)?\n\nÜber eine baldige Antwort würde ich mich sehr freuen.\n\nMit freundlichen Grüßen,\n[Ihr Name]', 'hinweise': ['اذكر الفترة الدقيقة للتأجير.', 'حدّد الفئة (Kompaktwagen, Mittelklasse, SUV).', 'اسأل عن التأمين الشامل (Vollkasko).', 'اسأل عن حدود الكيلومترات (Kilometerbegrenzung).']}, {'id': 'widerspruch-jobcenter', 'titleAr': 'اعتراض على قرار Jobcenter (رسمي مهم ⭐)', 'titleDe': 'Widerspruch gegen einen Jobcenter-Bescheid', 'typ': 'formal', 'scenario': 'استلمت قراراً من Jobcenter (تقليل Bürgergeld / رفض طلب) وتريد الاعتراض خلال شهر.', 'punkte': ['رقم الملف (Aktenzeichen)', 'تاريخ القرار', 'سبب الاعتراض', 'طلب المراجعة'], 'body': 'Jobcenter [Stadt]\nAbteilung Widerspruch\n[Adresse]\n\nWiderspruch gegen den Bescheid vom [Datum]\nAktenzeichen: [Ihr Aktenzeichen]\n\nSehr geehrte Damen und Herren,\n\ngegen den oben genannten Bescheid vom [Datum], zugestellt am [Datum], lege ich hiermit fristgerecht Widerspruch ein.\n\nBegründung:\nDer Bescheid ist aus folgenden Gründen nicht korrekt:\n1. Meine Miete wurde mit [Betrag] € berechnet, tatsächlich beträgt sie jedoch [Betrag] € (siehe Anlage: Mietvertrag).\n2. Die Heizkostenpauschale wurde nicht berücksichtigt, obwohl diese laut § 22 SGB II zu zahlen ist.\n3. Das Einkommen meiner Ehefrau wurde doppelt angerechnet.\n\nIch bitte Sie daher, den Bescheid zu überprüfen und einen neuen, korrekten Bescheid auszustellen.\n\nEine ausführliche Begründung sowie Belege reiche ich innerhalb von 14 Tagen nach.\n\nMit freundlichen Grüßen,\n[Ihr Name]\n[Adresse, Telefon]\n[Datum]', 'hinweise': ['⚠️ يجب إرسال الاعتراض خلال **شهر** من تاريخ استلام القرار.', 'أرسل الاعتراض بـ Einschreiben mit Rückschein (بريد مسجّل) لتحتفظ بإثبات التسليم.', 'اذكر Aktenzeichen دائماً (رقم الملف).', 'اذكر الأسباب مرقّمة وارفق Beweise (إثباتات).']}, {'id': 'widerspruch-krankenkasse', 'titleAr': 'اعتراض على قرار Krankenkasse (رسمي)', 'titleDe': 'Widerspruch gegen die Krankenkasse', 'typ': 'formal', 'scenario': 'الـKrankenkasse رفضت تمويل علاج/دواء تحتاجه. تعترض.', 'punkte': ['رقم التأمين', 'القرار المرفوض', 'الحاجة الطبّية', 'طلب المراجعة'], 'body': '[Name der Krankenkasse]\nAbteilung Widerspruch\n[Adresse]\n\nWiderspruch gegen den Bescheid vom [Datum]\nVersichertennummer: [Ihre Versichertennummer]\n\nSehr geehrte Damen und Herren,\n\ngegen Ihren Bescheid vom [Datum], in dem Sie die Kostenübernahme für [Behandlung/Medikament/Hilfsmittel] abgelehnt haben, lege ich hiermit fristgerecht Widerspruch ein.\n\nMeine behandelnde Ärztin, Frau Dr. [Name], hat diese Behandlung ausdrücklich verordnet (siehe beiliegendes Attest). Sie begründet die medizinische Notwendigkeit wie folgt: [kurze Begründung].\n\nOhne diese Behandlung verschlechtert sich mein Gesundheitszustand erheblich. Ich bitte Sie daher, Ihren Bescheid zu überprüfen und die Kosten vollständig zu übernehmen.\n\nAls Anlage füge ich bei:\n• Ärztliches Attest vom [Datum]\n• Kostenvoranschlag der Klinik/Apotheke\n• Auszug aus der Patientenakte\n\nÜber eine schnelle Bearbeitung würde ich mich sehr freuen.\n\nMit freundlichen Grüßen,\n[Ihr Name], Versicherter\n[Adresse, Telefon, Geburtsdatum]', 'hinweise': ['المهلة: شهر من استلام القرار.', 'ارفق تقرير الطبيب المعالج (ärztliches Attest).', 'اذكر رقم التأمين (Versichertennummer).', 'إن رُفض الاعتراض، يمكنك اللجوء إلى Sozialgericht (محكمة اجتماعية) مجاناً.']}, {'id': 'einspruch-bussgeld', 'titleAr': 'اعتراض على غرامة مرور (رسمي)', 'titleDe': 'Einspruch gegen einen Bußgeldbescheid', 'typ': 'formal', 'scenario': 'وصلتك غرامة مرور (إشارة حمراء / سرعة / وقوف خطأ) وتعتقد أنها غير عادلة.', 'punkte': ['رقم القرار (Aktenzeichen)', 'تاريخ المخالفة', 'سبب الاعتراض', 'طلب الإلغاء'], 'body': 'An die\nBußgeldstelle [Stadt]\n[Adresse]\n\nEinspruch gegen den Bußgeldbescheid vom [Datum]\nAktenzeichen: [Aktenzeichen]\n\nSehr geehrte Damen und Herren,\n\ngegen den oben genannten Bußgeldbescheid lege ich hiermit fristgerecht innerhalb der zweiwöchigen Frist Einspruch ein.\n\nBegründung:\nAm angegebenen Tag, den [Datum], um [Uhrzeit], war ich nicht der Fahrer des Fahrzeugs mit dem Kennzeichen [XX-XX 1234]. Das Fahrzeug wurde zu diesem Zeitpunkt von meinem Bruder, Herrn [Name], gefahren. Ein schriftliches Bestätigungsschreiben meines Bruders sowie seine Personalausweiskopie liegen als Anlage bei.\n\nIch bitte Sie daher, den Bußgeldbescheid aufzuheben und das Verfahren einzustellen.\n\nMit freundlichen Grüßen,\n[Ihr Name]\n[Adresse]', 'hinweise': ['⚠️ مهلة الاعتراض: **أسبوعان** فقط من استلام القرار.', 'ابعث الاعتراض بالبريد المسجّل (Einschreiben).', 'إذا كنت السائق فعلاً وقد أخطأت، يمكنك طلب تخفيف الغرامة (Gnadengesuch) بدلاً من الاعتراض.', 'في غرامات كبيرة، استشر محامي مرور (Verkehrsanwalt).']}];


